from topparse import parse
def gen(fn, off):
    prev=set(); order=[]
    for line in open(fn):
        n,rest=line.split(' ',1); n=int(n)
        cur=parse(rest)
        if n==1:
            continue
        if n==2:
            order=sorted(cur)  # 2 entries
            prev=cur; continue
        new=cur-prev
        if len(new)==1: order.append(list(new)[0])
        elif len(new)==0:
            if len(order)<n and any(True for _ in [0]):
                order.append(None)
        prev=cur
    # trim trailing Nones
    while order and order[-1] is None: order.pop()
    return [ (x-off if x is not None else -1) for x in order]
