#include "util.h"
#include <stdarg.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

int g_verbosity = 0;

void LOG(int level, const char *fmt, ...)
{
    va_list ap;
    if (level > g_verbosity)
        return;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fflush(stderr);
}

/* Compare option names, ignoring '-', '.', '_' and case. A trailing
 * "[n]" on the right-hand side is also accepted. */
int name_equals(const char *lhs, const char *rhs)
{
    for (;;) {
        while (*lhs == '-' || *lhs == '.' || *lhs == '_')
            lhs++;
        while (*rhs == '-' || *rhs == '.' || *rhs == '_')
            rhs++;
        if (*lhs == '\0' && *rhs == '[')
            return 1;
        if (tolower(*lhs & 0xFF) != tolower(*rhs & 0xFF))
            return 0;
        if (*lhs == '\0')
            return 1;
        lhs++;
        rhs++;
    }
}

uint64_t parse_int(const char *s)
{
    uint64_t r = 0;
    if (s == NULL)
        return 0;
    while (isdigit(*s & 0xFF)) {
        r = r * 10 + (uint64_t)(*s - '0');
        s++;
    }
    return r;
}

unsigned name_array_index(const char *rhs)
{
    const char *p = strchr(rhs, '[');
    if (p == NULL)
        return 0;
    p++;
    return (unsigned)parse_int(p);
}

int parse_boolean(const char *str)
{
    if (str == NULL || str[0] == '\0')
        return 1;
    if (isdigit(str[0] & 0xFF)) {
        if (strtoul(str, 0, 0) == 0)
            return 0;
        return 1;
    }
    switch (str[0]) {
    case 'e': case 'E': return 1;
    case 'd': case 'D': return 0;
    case 'y': case 'Y': return 1;
    case 'n': case 'N': return 0;
    case 'o': case 'O':
        if (str[1] == 'f' || str[1] == 'F')
            return 0;
        return 1;
    case 't': case 'T': return 1;
    case 'f': case 'F': return 0;
    }
    return 1;
}

int is_integer_str(const char *s)
{
    size_t i;
    if (s == NULL || s[0] == '\0')
        return 0;
    for (i = 0; s[i]; i++)
        if (!isdigit(s[i] & 0xFF))
            return 0;
    return 1;
}

int is_boolean_str(const char *s)
{
    if (s == NULL || s[0] == '\0')
        return 1;
    if (isdigit(s[0] & 0xFF)) {
        unsigned long n = strtoul(s, 0, 0);
        return n == 0 || n == 1;
    }
    switch (s[0]) {
    case 't': case 'T': case 'f': case 'F':
    case 'y': case 'Y': case 'n': case 'N':
    case 'e': case 'E': case 'd': case 'D':
    case 'o': case 'O':
        return 1;
    }
    return 0;
}

uint64_t parse_time_spec(const char *value)
{
    uint64_t num = 0;
    unsigned is_negative = 0;

    while (*value == '-') {
        is_negative = 1;
        value++;
    }
    while (isdigit(value[0] & 0xFF)) {
        num = num * 10 + (uint64_t)(value[0] - '0');
        value++;
    }
    while (ispunct(value[0] & 0xFF) || isspace(value[0] & 0xFF))
        value++;

    if (isalpha(value[0] & 0xFF) && num == 0)
        num = 1;

    if (value[0] == '\0')
        return num;

    switch (tolower(value[0] & 0xFF)) {
    case 's': num *= 1; break;
    case 'm': num *= 60; break;
    case 'h': num *= 60 * 60; break;
    case 'd': num *= 24 * 60 * 60; break;
    case 'w': num *= 24 * 60 * 60 * 7; break;
    default:
        fprintf(stderr, "--rotate-offset: unknown character\n");
        exit(1);
    }
    if (num >= 24 * 60 * 60) {
        fprintf(stderr, "--rotate-offset: value is greater than 1 day\n");
        exit(1);
    }
    if (is_negative)
        num = 24 * 60 * 60 - num;
    return num;
}

uint64_t parse_size_spec(const char *value)
{
    uint64_t num = 0;

    while (isdigit(value[0] & 0xFF)) {
        num = num * 10 + (uint64_t)(value[0] - '0');
        value++;
    }
    while (ispunct(value[0] & 0xFF) || isspace(value[0] & 0xFF))
        value++;

    if (isalpha(value[0] & 0xFF) && num == 0)
        num = 1;

    if (value[0] == '\0')
        return num;

    switch (tolower(value[0] & 0xFF)) {
    case 'k': num *= 1024ULL; break;
    case 'm': num *= 1024ULL * 1024ULL; break;
    case 'g': num *= 1024ULL * 1024ULL * 1024ULL; break;
    case 't': num *= 1024ULL * 1024ULL * 1024ULL * 1024ULL; break;
    case 'p': num *= 1024ULL * 1024ULL * 1024ULL * 1024ULL * 1024ULL; break;
    case 'e': num *= 1024ULL * 1024ULL * 1024ULL * 1024ULL * 1024ULL * 1024ULL; break;
    default:
        fprintf(stderr, "--rotate-size: unknown character\n");
        exit(1);
    }
    return num;
}

void trim_str(char *line, size_t sizeof_line)
{
    if (sizeof_line > strlen(line))
        sizeof_line = strlen(line);
    while (isspace(*line & 0xFF))
        memmove(line, line + 1, sizeof_line--);
    while (*line && isspace(line[sizeof_line - 1] & 0xFF))
        line[--sizeof_line] = '\0';
}

char *dup_str(const char *s)
{
    size_t n = strlen(s);
    char *r = malloc(n + 1);
    memcpy(r, s, n + 1);
    return r;
}

int str_icase_eq(const char *a, const char *b)
{
    while (*a && *b) {
        if (tolower(*a & 0xFF) != tolower(*b & 0xFF))
            return 0;
        a++; b++;
    }
    return *a == *b;
}

static const char b64[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

void base64_encode(char *dst, size_t sizeof_dst, const unsigned char *src, size_t len)
{
    size_t i = 0, d = 0;
    while (i + 2 < len) {
        unsigned x = (src[i] << 16) | (src[i+1] << 8) | src[i+2];
        if (d + 4 >= sizeof_dst) break;
        dst[d++] = b64[(x >> 18) & 0x3F];
        dst[d++] = b64[(x >> 12) & 0x3F];
        dst[d++] = b64[(x >> 6) & 0x3F];
        dst[d++] = b64[x & 0x3F];
        i += 3;
    }
    if (i < len && d + 4 < sizeof_dst) {
        unsigned x = src[i] << 16;
        if (i + 1 < len)
            x |= src[i+1] << 8;
        dst[d++] = b64[(x >> 18) & 0x3F];
        dst[d++] = b64[(x >> 12) & 0x3F];
        if (i + 1 < len)
            dst[d++] = b64[(x >> 6) & 0x3F];
        else
            dst[d++] = '=';
        dst[d++] = '=';
    }
    if (d < sizeof_dst)
        dst[d] = '\0';
}

static int b64val(int c)
{
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

size_t base64_decode(unsigned char *dst, size_t sizeof_dst, const char *src, size_t len)
{
    size_t i, d = 0;
    unsigned acc = 0;
    int bits = 0;
    for (i = 0; i < len; i++) {
        int v = b64val(src[i] & 0xFF);
        if (v < 0)
            continue;
        acc = (acc << 6) | (unsigned)v;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            if (d < sizeof_dst)
                dst[d++] = (unsigned char)((acc >> bits) & 0xFF);
        }
    }
    return d;
}
EOF
