#include "ranges.h"
#include "util.h"
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* ---------------------------------------------------------------- IPv4 */

void rangelist_add_range(struct RangeList *r, uint32_t begin, uint32_t end)
{
    if (begin > end)
        return;
    if (r->count + 1 >= r->max) {
        r->max = r->max * 2 + 16;
        r->list = realloc(r->list, r->max * sizeof(r->list[0]));
    }
    r->list[r->count].begin = begin;
    r->list[r->count].end = end;
    r->count++;
}

void rangelist_free(struct RangeList *r)
{
    free(r->list);
    r->list = NULL;
    r->count = r->max = 0;
}

static int cmp_range(const void *a, const void *b)
{
    const struct Range *x = a, *y = b;
    if (x->begin < y->begin) return -1;
    if (x->begin > y->begin) return 1;
    if (x->end < y->end) return -1;
    if (x->end > y->end) return 1;
    return 0;
}

void rangelist_sort(struct RangeList *r)
{
    size_t i, j;
    if (r->count == 0)
        return;
    qsort(r->list, r->count, sizeof(r->list[0]), cmp_range);
    j = 0;
    for (i = 1; i < r->count; i++) {
        struct Range *cur = &r->list[j];
        struct Range *nxt = &r->list[i];
        if ((uint64_t)nxt->begin <= (uint64_t)cur->end + 1) {
            if (nxt->end > cur->end)
                cur->end = nxt->end;
        } else {
            j++;
            r->list[j] = *nxt;
        }
    }
    r->count = j + 1;
}

uint64_t rangelist_count(const struct RangeList *r)
{
    uint64_t c = 0;
    size_t i;
    for (i = 0; i < r->count; i++)
        c += (uint64_t)r->list[i].end - r->list[i].begin + 1ULL;
    return c;
}

uint32_t rangelist_pick(const struct RangeList *r, uint64_t index)
{
    size_t i;
    for (i = 0; i < r->count; i++) {
        uint64_t n = (uint64_t)r->list[i].end - r->list[i].begin + 1ULL;
        if (index < n)
            return (uint32_t)(r->list[i].begin + index);
        index -= n;
    }
    return 0;
}

int rangelist_is_contains(const struct RangeList *r, uint32_t n)
{
    size_t i;
    for (i = 0; i < r->count; i++)
        if (r->list[i].begin <= n && n <= r->list[i].end)
            return 1;
    return 0;
}

void rangelist_exclude(struct RangeList *targets, struct RangeList *excludes)
{
    struct RangeList out = {0};
    size_t i, j;
    rangelist_sort(targets);
    rangelist_sort(excludes);
    for (i = 0; i < targets->count; i++) {
        uint64_t b = targets->list[i].begin;
        uint64_t e = targets->list[i].end;
        for (j = 0; j < excludes->count && b <= e; j++) {
            uint64_t xb = excludes->list[j].begin;
            uint64_t xe = excludes->list[j].end;
            if (xe < b || xb > e)
                continue;
            if (xb > b)
                rangelist_add_range(&out, (uint32_t)b, (uint32_t)(xb - 1));
            b = xe + 1;
        }
        if (b <= e)
            rangelist_add_range(&out, (uint32_t)b, (uint32_t)e);
    }
    free(targets->list);
    *targets = out;
}

/* ---------------------------------------------------------------- IPv6 */

void range6list_add_range(struct Range6List *r, u128 begin, u128 end)
{
    if (r->count + 1 >= r->max) {
        r->max = r->max * 2 + 16;
        r->list = realloc(r->list, r->max * sizeof(r->list[0]));
    }
    r->list[r->count].begin = begin;
    r->list[r->count].end = end;
    r->count++;
}

static int cmp_range6(const void *a, const void *b)
{
    const struct Range6 *x = a, *y = b;
    if (x->begin < y->begin) return -1;
    if (x->begin > y->begin) return 1;
    if (x->end < y->end) return -1;
    if (x->end > y->end) return 1;
    return 0;
}

void range6list_sort(struct Range6List *r)
{
    size_t i, j;
    if (r->count == 0)
        return;
    qsort(r->list, r->count, sizeof(r->list[0]), cmp_range6);
    j = 0;
    for (i = 1; i < r->count; i++) {
        struct Range6 *cur = &r->list[j];
        struct Range6 *nxt = &r->list[i];
        u128 ce1 = cur->end + 1;
        if (nxt->begin <= cur->end || (ce1 != 0 && nxt->begin == ce1)) {
            if (nxt->end > cur->end)
                cur->end = nxt->end;
        } else {
            j++;
            r->list[j] = *nxt;
        }
    }
    r->count = j + 1;
}

u128 range6list_count(const struct Range6List *r, int *overflow)
{
    u128 c = 0;
    size_t i;
    if (overflow) *overflow = 0;
    for (i = 0; i < r->count; i++) {
        u128 n = r->list[i].end - r->list[i].begin + 1;
        if (n == 0) {
            if (overflow) *overflow = 1;
            n = ~(u128)0;
        }
        if (c + n < c) {
            if (overflow) *overflow = 1;
            c = ~(u128)0;
        } else
            c += n;
    }
    return c;
}

u128 range6list_pick(const struct Range6List *r, uint64_t index)
{
    size_t i;
    u128 idx = index;
    for (i = 0; i < r->count; i++) {
        u128 n = r->list[i].end - r->list[i].begin + 1;
        if (n == 0 || idx < n)
            return r->list[i].begin + idx;
        idx -= n;
    }
    return 0;
}

void range6list_exclude(struct Range6List *targets, struct Range6List *excludes)
{
    struct Range6List out = {0};
    size_t i, j;
    range6list_sort(targets);
    range6list_sort(excludes);
    for (i = 0; i < targets->count; i++) {
        u128 b = targets->list[i].begin;
        u128 e = targets->list[i].end;
        int done = 0;
        for (j = 0; j < excludes->count && !done; j++) {
            u128 xb = excludes->list[j].begin;
            u128 xe = excludes->list[j].end;
            if (xe < b || xb > e)
                continue;
            if (xb > b)
                range6list_add_range(&out, b, xb - 1);
            if (xe >= e) {
                done = 1;
                break;
            }
            b = xe + 1;
        }
        if (!done && b <= e)
            range6list_add_range(&out, b, e);
    }
    free(targets->list);
    *targets = out;
}

unsigned u128_bitcount(u128 x)
{
    unsigned n = 0;
    while (x) {
        n++;
        x >>= 1;
    }
    return n;
}

/* ---------------------------------------------------------------- format */

void format_ipv4(char *buf, size_t n, uint32_t ip)
{
    snprintf(buf, n, "%u.%u.%u.%u", (ip >> 24) & 0xFF, (ip >> 16) & 0xFF, (ip >> 8) & 0xFF, ip & 0xFF);
}

void format_ipv6(char *buf, size_t n, u128 ip)
{
    unsigned g[8];
    int i, z = -1, e;
    size_t len = 0;
    for (i = 0; i < 8; i++)
        g[i] = (unsigned)((ip >> (112 - 16 * i)) & 0xFFFF);
    for (i = 0; i < 8; i++)
        if (g[i] == 0) { z = i; break; }
    buf[0] = '\0';
    if (z < 0) {
        for (i = 0; i < 8; i++)
            len += snprintf(buf + len, n - len, i ? ":%x" : "%x", g[i]);
        return;
    }
    e = z;
    while (e < 8 && g[e] == 0)
        e++;
    for (i = 0; i < z; i++)
        len += snprintf(buf + len, n - len, i ? ":%x" : "%x", g[i]);
    len += snprintf(buf + len, n - len, "::");
    for (i = e; i < 8; i++)
        len += snprintf(buf + len, n - len, i > e ? ":%x" : "%x", g[i]);
}

/* greedy CIDR splitting, IPv4, with the begin==0 quirk */
static unsigned cidr4_block(uint32_t b, uint32_t e, uint64_t *size)
{
    unsigned k;
    if (b == 0) {
        if (e == 0xFFFFFFFF) {
            *size = 0x100000000ULL;
            return 0;
        }
        *size = 1;
        return 0;
    }
    k = 0;
    while (k < 32 && !(b & (1U << k)))
        k++;
    while (k > 0 && (uint64_t)b + ((1ULL << k) - 1) > e)
        k--;
    *size = 1ULL << k;
    return 32 - k;
}

void print_range4(FILE *fp, uint32_t begin, uint32_t end)
{
    char a[32], b[32];
    format_ipv4(a, sizeof(a), begin);
    if (begin == end) {
        fprintf(fp, "%s\n", a);
        return;
    } else {
        uint64_t size;
        unsigned prefix = cidr4_block(begin, end, &size);
        if ((uint64_t)begin + size - 1 == end) {
            fprintf(fp, "%s/%u\n", a, prefix);
            return;
        }
    }
    format_ipv4(b, sizeof(b), end);
    fprintf(fp, "%s-%s\n", a, b);
}

void echo_cidr4(FILE *fp, uint32_t begin, uint32_t end)
{
    uint64_t b = begin;
    while (b <= end) {
        uint64_t size;
        char a[32];
        unsigned prefix = cidr4_block((uint32_t)b, end, &size);
        format_ipv4(a, sizeof(a), (uint32_t)b);
        fprintf(fp, "%s/%u\n", a, prefix);
        b += size;
    }
}

static int is_cidr6(u128 begin, u128 end, unsigned *prefix)
{
    u128 n = end - begin + 1;
    unsigned bits;
    if (n == 0)
        return 0;
    if (n & (n - 1))
        return 0;
    if (begin & (n - 1))
        return 0;
    bits = u128_bitcount(n) - 1;
    *prefix = 128 - bits;
    return 1;
}

void print_range6(FILE *fp, u128 begin, u128 end)
{
    char a[64], b[64];
    unsigned prefix;
    format_ipv6(a, sizeof(a), begin);
    if (begin == end) {
        fprintf(fp, "%s\n", a);
        return;
    }
    if (is_cidr6(begin, end, &prefix)) {
        fprintf(fp, "%s/%u\n", a, prefix);
        return;
    }
    format_ipv6(b, sizeof(b), end);
    fprintf(fp, "%s-%s\n", a, b);
}

void echo_cidr6(FILE *fp, u128 begin, u128 end)
{
    u128 b = begin;
    char a[64];
    if (begin == 0 && end == ~(u128)0) {
        fprintf(fp, "::/0\n");
        return;
    }
    for (;;) {
        unsigned k = 0;
        u128 size;
        while (k < 128 && !((b >> k) & 1))
            k++;
        if (k > 127) k = 127;
        while (k > 0 && (b + (((u128)1 << k) - 1) > end || b + (((u128)1 << k) - 1) < b))
            k--;
        size = (u128)1 << k;
        format_ipv6(a, sizeof(a), b);
        fprintf(fp, "%s/%u\n", a, 128 - k);
        if (b + size - 1 >= end)
            break;
        b += size;
    }
}

/* ---------------------------------------------------------------- parsing */

static int is_term(int c)
{
    return c == '\0' || c == ',' || isspace(c & 0xFF);
}

/* parse IPv4 dotted address at s[*p]; returns 1 ok, 0 error */
static int parse_v4(const char *s, size_t *p, size_t len, uint32_t *out)
{
    unsigned octets = 0;
    uint32_t result = 0;
    size_t i = *p;
    for (;;) {
        unsigned val = 0, digits = 0;
        while (i < len && isdigit(s[i] & 0xFF)) {
            val = val * 10 + (unsigned)(s[i] - '0');
            digits++;
            if (digits > 3)
                return 0;
            i++;
        }
        if (val > 255)
            return 0;
        result = (result << 8) | val;
        octets++;
        if (i < len && s[i] == '.') {
            if (octets >= 4)
                return 0;
            i++;
            continue;
        }
        break;
    }
    if (octets != 4)
        return 0;
    *p = i;
    *out = result;
    return 1;
}

static int hexval(int c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static int parse_v6(const char *s, size_t *p, size_t len, u128 *out)
{
    unsigned groups[8];
    int ngroups = 0;
    int dbl = -1;
    size_t i = *p;
    int k;

    if (i + 1 < len && s[i] == ':' && s[i+1] == ':') {
        dbl = 0;
        i += 2;
    } else if (i < len && s[i] == ':') {
        return 0;
    }
    for (;;) {
        unsigned val = 0, digits = 0;
        while (i < len && hexval(s[i] & 0xFF) >= 0) {
            val = val * 16 + (unsigned)hexval(s[i] & 0xFF);
            digits++;
            if (digits > 4)
                return 0;
            i++;
        }
        if (digits == 0) {
            /* allowed only right after a '::' */
            if (dbl >= 0 && dbl == ngroups && (i == *p + 2 || (i >= 2 && s[i-1] == ':' && s[i-2] == ':')))
                break;
            return 0;
        }
        if (ngroups >= 8)
            return 0;
        groups[ngroups++] = val;
        if (i < len && s[i] == ':') {
            if (i + 1 < len && s[i+1] == ':') {
                if (dbl >= 0)
                    return 0;
                dbl = ngroups;
                i += 2;
                if (i < len && s[i] == ':')
                    return 0;
                continue;
            }
            i++;
            continue;
        }
        break;
    }
    if (dbl < 0 && ngroups != 8)
        return 0;
    if (dbl >= 0 && ngroups > 7)
        return 0;
    {
        u128 r = 0;
        unsigned full[8];
        int fill = 8 - ngroups;
        int idx = 0;
        for (k = 0; k < ngroups; k++) {
            if (k == dbl) {
                int f;
                for (f = 0; f < fill; f++)
                    full[idx++] = 0;
            }
            full[idx++] = groups[k];
        }
        if (dbl == ngroups) {
            int f;
            for (f = 0; f < fill; f++)
                full[idx++] = 0;
        }
        for (k = 0; k < 8; k++)
            r = (r << 16) | full[k];
        *out = r;
    }
    *p = i;
    return 1;
}

static int looks_v4(const char *s, size_t p, size_t len)
{
    while (p < len && isdigit(s[p] & 0xFF))
        p++;
    return p < len && s[p] == '.';
}

/* returns 4, 6, 0 (nothing), -1 (error) */
static int parse_one_range(const char *s, size_t *off, size_t len, struct Range *r4, struct Range6 *r6)
{
    size_t p = *off;
    int c;

    while (p < len && isspace(s[p] & 0xFF))
        p++;
    if (p >= len) {
        *off = p;
        return 0;
    }
    c = s[p] & 0xFF;
    if (c == '#' || c == '-' || c == '/' || c == ';') {
        LOG(0, "[-] _parser_next(): unknown coding failure\n");
        return -1;
    }
    if (isdigit(c) && looks_v4(s, p, len)) {
        uint32_t a, b;
        if (!parse_v4(s, &p, len, &a))
            return -1;
        if (p < len && s[p] == '/') {
            unsigned prefix = 0, digits = 0;
            p++;
            while (p < len && isdigit(s[p] & 0xFF)) {
                prefix = prefix * 10 + (unsigned)(s[p] - '0');
                digits++;
                if (digits > 3)
                    return -1;
                p++;
            }
            if (prefix > 32)
                return -1;
            if (!(p >= len || is_term(s[p])))
                return -1;
            {
                uint32_t mask = prefix ? (0xFFFFFFFFU << (32 - prefix)) : 0;
                r4->begin = a & mask;
                r4->end = (a & mask) | ~mask;
            }
            *off = p;
            return 4;
        } else if (p < len && s[p] == '-') {
            p++;
            if (!(p < len && isdigit(s[p] & 0xFF) && looks_v4(s, p, len)))
                return -1;
            if (!parse_v4(s, &p, len, &b))
                return -1;
            if (!(p >= len || is_term(s[p])))
                return -1;
            r4->begin = a;
            r4->end = b;
            *off = p;
            return 4;
        } else if (p >= len || is_term(s[p])) {
            r4->begin = a;
            r4->end = a;
            *off = p;
            return 4;
        }
        return -1;
    }
    if (c == '[' || c == ':' || hexval(c) >= 0) {
        u128 a, b;
        int bracket = 0;
        if (c == '[') {
            bracket = 1;
            p++;
        }
        if (!parse_v6(s, &p, len, &a))
            return -1;
        if (bracket && p < len && s[p] == ']')
            p++;
        else if (!bracket && p < len && s[p] == ']')
            return -1;
        if (p < len && s[p] == '/') {
            unsigned prefix = 0, digits = 0;
            p++;
            while (p < len && isdigit(s[p] & 0xFF)) {
                prefix = prefix * 10 + (unsigned)(s[p] - '0');
                digits++;
                if (digits > 4)
                    return -1;
                p++;
            }
            if (digits == 0 || prefix > 128)
                return -1;
            if (!(p >= len || is_term(s[p])))
                return -1;
            {
                u128 mask = prefix ? (~(u128)0 << (128 - prefix)) : 0;
                r6->begin = a & mask;
                r6->end = (a & mask) | ~mask;
            }
            *off = p;
            return 6;
        } else if (p < len && s[p] == '-') {
            int br2 = 0;
            p++;
            if (p < len && s[p] == '[') {
                br2 = 1;
                p++;
            }
            if (p >= len)
                return -1;
            if (looks_v4(s, p, len))
                return -1;
            if (!parse_v6(s, &p, len, &b))
                return -1;
            if (br2 && p < len && s[p] == ']')
                p++;
            if (!(p >= len || is_term(s[p])))
                return -1;
            r6->begin = a;
            r6->end = b;
            *off = p;
            return 6;
        } else if (p >= len || is_term(s[p])) {
            r6->begin = a;
            r6->end = a;
            *off = p;
            return 6;
        }
        return -1;
    }
    return -1;
}

int massip_add_target_string(struct MassIP *massip, const char *string)
{
    size_t offset = 0;
    size_t max_offset = strlen(string);

    while (offset < max_offset) {
        struct Range r4;
        struct Range6 r6;
        int x = parse_one_range(string, &offset, max_offset, &r4, &r6);
        if (x == 4)
            rangelist_add_range(&massip->ipv4, r4.begin, r4.end);
        else if (x == 6)
            range6list_add_range(&massip->ipv6, r6.begin, r6.end);
        else if (x == 0)
            break;
        else
            return 1;
        while (offset < max_offset && (isspace(string[offset] & 0xFF) || string[offset] == ','))
            offset++;
    }
    return 0;
}

int parse_ip_address(const char *s, uint32_t *ipv4, u128 *ipv6)
{
    size_t p = 0, len = strlen(s);
    if (looks_v4(s, 0, len)) {
        if (parse_v4(s, &p, len, ipv4) && p == len)
            return 4;
        return 0;
    }
    if (parse_v6(s, &p, len, ipv6) && p == len)
        return 6;
    return 0;
}

/* ---------------------------------------------------------------- ports */

const char *rangelist_parse_ports(struct RangeList *ports, const char *string, unsigned *is_error, unsigned proto_offset_in)
{
    const char *p = string;
    unsigned proto_offset = proto_offset_in;
    unsigned tmp = 0;
    if (is_error == NULL)
        is_error = &tmp;
    *is_error = 0;

    while (*p) {
        unsigned long port, end;
        unsigned max = 65535;
        char *q;

        while (*p && isspace(*p & 0xFF))
            p++;
        if (*p == 0 || *p == '#')
            break;

        if (isalpha(*p & 0xFF) && p[1] == ':') {
            switch (*p) {
            case 'T': case 't': proto_offset = 0; break;
            case 'U': case 'u': proto_offset = Templ_UDP; break;
            case 'S': case 's': proto_offset = Templ_SCTP; break;
            case 'O': case 'o': proto_offset = Templ_Oproto_first; break;
            case 'I': case 'i': proto_offset = Templ_ICMP_echo; break;
            default:
                LOG(0, "bad port character = %c\n", p[0]);
                *is_error = 1;
                return p;
            }
            p += 2;
        }
        if (proto_offset == Templ_Oproto_first)
            max = 255;

        if (*p == '-') {
            port = 1;
        } else if (!isdigit(*p & 0xFF)) {
            break;
        } else {
            port = strtoul(p, &q, 0);
            p = q;
        }
        end = port;
        if (*p == '-') {
            p++;
            if (isdigit(*p & 0xFF)) {
                end = strtoul(p, &q, 0);
                p = q;
            } else
                end = max;
        }
        port = (unsigned)port;
        end = (unsigned)end;
        if (port > max || end > max || end < port) {
            *is_error = 2;
            return p;
        }
        rangelist_add_range(ports, (uint32_t)(port + proto_offset), (uint32_t)(end + proto_offset));
        if (*p == ',')
            p++;
        else
            break;
    }
    return p;
}

void massip_optimize(struct MassIP *m)
{
    rangelist_sort(&m->ipv4);
    range6list_sort(&m->ipv6);
    rangelist_sort(&m->ports);
    m->count_ports = (unsigned)rangelist_count(&m->ports);
    m->ipv4_index_threshold = rangelist_count(&m->ipv4) * m->count_ports;
}
EOF
echo ok

