static int parse_mac(const char *text, unsigned char *mac)
{
    unsigned i;
    for (i = 0; i < 6; i++) {
        int hi, lo;
        while (isspace(*text & 0xFF) && ispunct(*text & 0xFF))
            text++;
        if (!isxdigit(*text & 0xFF))
            return -1;
        hi = isdigit(*text & 0xFF) ? *text - '0' : (tolower(*text & 0xFF) - 'a' + 10);
        text++;
        if (!isxdigit(*text & 0xFF))
            return -1;
        lo = isdigit(*text & 0xFF) ? *text - '0' : (tolower(*text & 0xFF) - 'a' + 10);
        text++;
        mac[i] = (unsigned char)((hi << 4) | lo);
        if (ispunct(*text & 0xFF))
            text++;
    }
    return 0;
}

static int mac_is_zero(const unsigned char *mac)
{
    return memcmp(mac, "\0\0\0\0\0\0", 6) == 0;
