static void set_adapter_ip(struct Masscan *m, const char *name, const char *value)
{
    struct NicConf *nic = get_nic(m, name);
    struct MassIP tmp;
    int err;
    memset(&tmp, 0, sizeof(tmp));
    err = massip_add_target_string(&tmp, value);
    if (tmp.ipv4.count == 0 && tmp.ipv6.count == 0) {
        (void)err;
        fprintf(stderr, "FAIL: bad source IP address: %s=%s\n", name, value);
        fprintf(stderr, "hint   addresses look like \"192.168.1.23\" or \"2001:db8:1::1ce9\".\n");
        exit(1);
    }
    if (tmp.ipv4.count) {
        uint32_t b = tmp.ipv4.list[0].begin, e = tmp.ipv4.list[0].end;
        uint64_t n = (uint64_t)e - b + 1;
        if (n & (n - 1)) {
            fprintf(stderr, "FAIL: range must be even power of two: %s=%s\n", name, value);
            exit(1);
        }
        nic->src_ipv4_first = b;
        nic->src_ipv4_last = e;
        nic->has_src_ipv4 = 1;
    } else {
        u128 b = tmp.ipv6.list[0].begin, e = tmp.ipv6.list[0].end;
        u128 n = e - b + 1;
        if (n & (n - 1)) {
            fprintf(stderr, "FAIL: range must be even power of two: %s=%s\n", name, value);
            exit(1);
        }
        nic->src_ipv6_first = b;
        nic->src_ipv6_last = e;
        nic->has_src_ipv6 = 1;
    }
    free(tmp.ipv4.list);
    free(tmp.ipv6.list);
}

