static int SET_rate(struct Masscan *m, const char *name, const char *value)
{
    double rate = 0.0;
    double point = 10.0;
    unsigned i;

    if (m->echo) {
        if ((unsigned)(uint64_t)(m->max_rate * 100000) % 100000) {
            fprintf(m->echo, "rate = %f\n", m->max_rate);
        } else {
            fprintf(m->echo, "rate = %-10.0f\n", m->max_rate);
        }
        return 0;
    }

    for (i = 0; value[i] && value[i] != '.'; i++) {
        char c = value[i];
        if (c < '0' || '9' < c) {
            fprintf(stderr, "CONF: non-digit in rate spec: %s=%s\n", name, value);
            return 1;
        }
        rate = rate * 10.0 + (c - '0');
    }
    if (value[i] == '.') {
        i++;
        while (value[i]) {
            char c = value[i];
            if (c < '0' || '9' < c) {
                fprintf(stderr, "CONF: non-digit in rate spec: %s=%s\n", name, value);
                return 1;
            }
            rate += (c - '0') / point;
            point *= 10.0;
            value++;
        }
    }
    m->max_rate = rate;
    return 0;
}

static int SET_shard(struct Masscan *m, const char *name, const char *value)
{
    unsigned one = 0, of = 0;
    (void)name;
    if (m->echo) {
        if (m->shard.of > 0 || m->echo_all)
            fprintf(m->echo, "shard = %u/%u\n", m->shard.one, m->shard.of);
        return 0;
    }
    while (isdigit(*value & 0xFF))
        one = one * 10 + (unsigned)(*(value++) - '0');
    while (ispunct(*value & 0xFF))
        value++;
    while (isdigit(*value & 0xFF))
        of = of * 10 + (unsigned)(*(value++) - '0');

    if (one < 1) {
        fprintf(stderr, "FAIL: shard index can't be zero\n");
        fprintf(stderr, "hint   it goes like 1/4 2/4 3/4 4/4\n");
        return 1;
    }
    if (one > of) {
        fprintf(stderr, "FAIL: shard spec is wrong\n");
        fprintf(stderr, "hint   it goes like 1/4 2/4 3/4 4/4\n");
        return 1;
    }
    m->shard.one = one;
    m->shard.of = of;
    return 0;
}

