static void add_hello(struct Masscan *m, unsigned index, const char *b64)
{
    size_t i;
    for (i = 0; i < m->hello_count; i++) {
        if (m->hellos[i].index == index) {
            set_string(&m->hellos[i].value, b64);
            return;
        }
    }
    m->hellos = realloc(m->hellos, (m->hello_count + 1) * sizeof(m->hellos[0]));
    m->hellos[m->hello_count].index = index;
    m->hellos[m->hello_count].value = dup_str(b64);
    m->hello_count++;
}

static int SET_hello_file(struct Masscan *m, const char *name, const char *value)
