    FILE *fp;
    unsigned char buf[16384];
    char *b64;
    size_t bytes;

    if (m->echo)
        return 0;
    index = name_array_index(name);
    fp = fopen(value, "rb");
    if (fp == NULL) {
        int x = errno;
        fprintf(stderr, "[-] [FAILED] --hello-file\n");
        fprintf(stderr, "[-] %s: %s\n", value, strerror(x));
        exit(1);
    }
    bytes = fread(buf, 1, sizeof(buf), fp);
    fclose(fp);
    b64 = malloc(bytes * 2 + 16);
    base64_encode(b64, bytes * 2 + 16, buf, bytes);
    add_hello(m, index, b64);
    free(b64);
    return 0;
}

