    if (strchr(value, ':') == NULL) {
        fprintf(stderr, "[-] --http-header needs both a name and value\n");
        fprintf(stderr, "    hint: \"--http-header Name:value\"\n");
        exit(1);
    }
    m->http_headers = realloc(m->http_headers, (m->http_header_count + 1) * sizeof(char *));
    m->http_headers[m->http_header_count++] = dup_str(value);
    return 0;
}

