static void echo_capture(struct Masscan *m)
{
    FILE *fp = m->echo;
    if (!m->is_capture_cert || m->echo_all)
        fprintf(fp, "%scapture = cert\n", m->is_capture_cert ? "" : "no");
    if (!m->is_capture_servername || m->echo_all)
        fprintf(fp, "%scapture = servername\n", m->is_capture_servername ? "" : "no");
    if (m->is_capture_html || m->echo_all)
        fprintf(fp, "%scapture = html\n", m->is_capture_html ? "" : "no");
    if (m->is_capture_heartbleed || m->echo_all)
        fprintf(fp, "%scapture = heartbleed\n", m->is_capture_heartbleed ? "" : "no");
    if (m->is_capture_ticketbleed || m->echo_all)
        fprintf(fp, "%scapture = ticketbleed\n", m->is_capture_ticketbleed ? "" : "no");
}

static int set_capture_common(struct Masscan *m, const char *name, const char *value, int is_capture)
{
    (void)name;
    if (m->echo) {
        echo_capture(m);
        return 0;
    }
    if (name_equals("cert", value))
        m->is_capture_cert = is_capture;
    else if (name_equals("servername", value))
        m->is_capture_servername = is_capture;
    else if (name_equals("html", value))
        m->is_capture_html = is_capture;
    else if (name_equals("heartbleed", value))
        m->is_capture_heartbleed = is_capture;
    else if (name_equals("ticketbleed", value))
        m->is_capture_ticketbleed = is_capture;
    else {
        fprintf(stderr, "FAIL: %s: unknown %s type\n", value, is_capture ? "capture" : "nocapture");
        return 1;
    }
    return 0;
}

