static const char *format_name(int fmt)
{
    switch (fmt) {
    case Output_Interactive: return "interactive";
    case Output_List: return "list";
    case Output_Unicornscan: return "unicornscan";
    case Output_XML: return "xml";
    case Output_Binary: return "binary";
    case Output_Grepable: return "grepable";
    case Output_JSON: return "json";
    case Output_NDJSON: return "ndjson";
    case Output_Certs: return "certs";
    case Output_None: return "none";
    case Output_Redis: return "redis";
    case Output_Hostonly: return "hostonly";
    default: return NULL;
    }
}

static int SET_output_format(struct Masscan *m, const char *name, const char *value)
{
    (void)name;
    if (m->echo) {
        const char *s = format_name(m->output.format);
        if (s) {
            fprintf(m->echo, "output-format = %s\n", s);
            if (m->output.format == Output_Redis) {
                uint32_t ip = m->output.redis_ip;
                fprintf(m->echo, "redis = %u.%u.%u.%u %u\n",
                        (ip >> 24) & 0xFF, (ip >> 16) & 0xFF, (ip >> 8) & 0xFF, ip & 0xFF,
                        m->output.redis_port);
            }
        } else if (m->output.format != 0) {
            fprintf(m->echo, "output-format = unknown(%u)\n", m->output.format);
        }
        return 0;
    }
    if (name_equals("unknown(0)", value))      m->output.format = Output_Interactive;
    else if (name_equals("interactive", value)) m->output.format = Output_Interactive;
    else if (name_equals("list", value))        m->output.format = Output_List;
    else if (name_equals("unicornscan", value)) m->output.format = Output_Unicornscan;
    else if (name_equals("xml", value))         m->output.format = Output_XML;
    else if (name_equals("binary", value))      m->output.format = Output_Binary;
    else if (name_equals("greppable", value))   m->output.format = Output_Grepable;
    else if (name_equals("grepable", value))    m->output.format = Output_Grepable;
    else if (name_equals("json", value))        m->output.format = Output_JSON;
    else if (name_equals("ndjson", value))      m->output.format = Output_NDJSON;
    else if (name_equals("certs", value))       m->output.format = Output_Certs;
    else if (name_equals("none", value))        m->output.format = Output_None;
    else if (name_equals("redis", value))       m->output.format = Output_Redis;
    else if (name_equals("hostonly", value))    m->output.format = Output_Hostonly;
    else {
        fprintf(stderr, "FAIL: unknown output-format: %s\n", value);
        fprintf(stderr, "  hint: 'binary', 'xml', 'grepable', ...\n");
        return 1;
    }
    return 0;
}

static int SET_output_show(struct Masscan *m, const char *name, const char *value)
{
    (void)name;
    if (m->echo)
        return 0;
    for (;;) {
        const char *val2 = value;
        unsigned val2_len;
        while (*val2 && *val2 != ',')
            val2++;
        val2_len = (unsigned)(val2 - value);
        if (val2_len == 4 && strncasecmp(value, "open", 4) == 0)
            m->output.is_show_open = 1;
        else if (val2_len == 6 && strncasecmp(value, "closed", 6) == 0)
            m->output.is_show_closed = 1;
        else if (val2_len == 4 && strncasecmp(value, "host", 4) == 0)
            m->output.is_show_host = 1;
        else if (val2_len == 3 && strncasecmp(value, "all", 3) == 0) {
            m->output.is_show_open = 1;
            m->output.is_show_host = 1;
            m->output.is_show_closed = 1;
        } else {
            fprintf(stderr, "FAIL: unknown 'show' spec: %.*s\n", val2_len, value);
            exit(1);
        }
        value = val2;
        if (*value == ',')
            value++;
        if (*value == '\0')
            break;
    }
    return 0;
}

