static int set_tcp_opt(struct Masscan *m, struct TcpOpt *opt, const char *name, const char *value, unsigned max)
{
    if (m->echo) {
        if (opt->is_set == 1) {
            if (opt->value == opt->dflt)
                fprintf(m->echo, "%s = enable\n", name);
            else
                fprintf(m->echo, "%s = %u\n", name, opt->value);
        } else if (opt->is_set == 2) {
            fprintf(m->echo, "%s = disable\n", name);
        }
        return 0;
    }
    if (is_boolean_str(value)) {
        if (parse_boolean(value)) {
            opt->is_set = 1;
            opt->value = opt->dflt;
        } else {
            opt->is_set = 2;
        }
        return 0;
    }
    if (is_integer_str(value)) {
        uint64_t n = parse_int(value);
        if (n > max) {
            fprintf(stderr, "[-] %s: bad value: %s\n", name, value);
            return 1;
        }
        opt->is_set = 1;
        opt->value = (unsigned)n;
        return 0;
    }
    fprintf(stderr, "[-] %s: bad value: %s\n", name, value);
    return 1;
}

