void config_top_ports(struct Masscan *m, unsigned n)
{
    unsigned i;
    if (m->scan_type.tcp) {
        for (i = 0; i < n && i < top_tcp_ports_count; i++)
            rangelist_add_range(&m->targets.ports, top_tcp_ports[i], top_tcp_ports[i]);
    }
    if (m->scan_type.udp) {
        for (i = 0; i < n && i < top_udp_ports_count; i++)
            rangelist_add_range(&m->targets.ports, Templ_UDP + top_udp_ports[i], Templ_UDP + top_udp_ports[i]);
    }
    rangelist_sort(&m->targets.ports);
}

void masscan_read_config_file(struct Masscan *m, const char *filename)
{
    FILE *fp;
    char *line;
    size_t linesize = 65536;

    fp = fopen(filename, "rt");
    if (fp == NULL) {
        char dir[512];
        int x = errno;
        fprintf(stderr, "[-] FAIL: reading configuration file\n");
        fprintf(stderr, "[-] %s: %s\n", filename, strerror(x));
        if (getcwd(dir, sizeof(dir)))
            fprintf(stderr, "[-] cwd = %s\n", dir);
        return;
    }
    line = malloc(linesize);
    while (fgets(line, (int)linesize, fp)) {
        char *name;
        char *value;

        trim_str(line, linesize);
        if (ispunct(line[0] & 0xFF) || line[0] == '\0')
            continue;
        name = line;
        value = strchr(line, '=');
        if (value == NULL)
            continue;
        *value = '\0';
        value++;
        trim_str(name, linesize);
        trim_str(value, linesize);
        masscan_set_parameter(m, name, value);
    }
    free(line);
    fclose(fp);
}

