static uint64_t get_entropy(void)
{
    uint64_t x = 0;
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd >= 0) {
        if (read(fd, &x, sizeof(x)) != sizeof(x))
            x = 0;
        close(fd);
    }
    if (x == 0) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        x = ((uint64_t)ts.tv_sec << 32) ^ (uint64_t)ts.tv_nsec ^ (uint64_t)getpid();
    }
    return x;
}

int main(int argc, char *argv[])
{
    static struct Masscan masscan[1];
    struct Masscan *m = masscan;
    int has_target_addresses = 0;
    int has_target_ports = 0;

    setvbuf(stderr, NULL, _IONBF, 0);
    masscan_init(m);

    masscan_command_line(m, argc, argv);

    if (m->seed == 0)
        m->seed = get_entropy();

    masscan_load_database_files(m);

    pcap_init_messages();

    /* apply excludes */
    {
        has_target_addresses = (m->targets.ipv4.count != 0) || (m->targets.ipv6.count != 0);
        has_target_ports = m->targets.ports.count != 0;
        rangelist_exclude(&m->targets.ipv4, &m->exclude.ipv4);
        range6list_exclude(&m->targets.ipv6, &m->exclude.ipv6);
        rangelist_exclude(&m->targets.ports, &m->exclude.ports);
        massip_optimize(&m->targets);
    }

    /* check range size */
    {
        int overflow = 0;
        u128 c6 = range6list_count(&m->targets.ipv6, &overflow);
        u128 c4 = rangelist_count(&m->targets.ipv4);
        u128 ports = rangelist_count(&m->targets.ports);
        u128 total;
        unsigned bits;
        if (ports == 0) {
            bits = 0;
        } else {
            u128 ips = c4 + c6;
            if (ips < c6 || overflow)
                ips = ~(u128)0;
            if (ips && ports > (~(u128)0) / ips)
                total = ~(u128)0;
            else
                total = ips * ports;
            bits = u128_bitcount(total);
        }
        if (bits > 63) {
            fprintf(stderr, "[-] FAIL: scan range too large, max is 63-bits, requested is %u bits\n", bits);
            fprintf(stderr, "    Hint: scan range is number of IP addresses times number of ports\n");
            fprintf(stderr, "    Hint: IPv6 subnet must be at least /66 \n");
            exit(1);
        }
    }

    switch (m->op) {
    case Operation_Default:
        masscan_usage();
        break;
    case Operation_Scan:
        if (rangelist_count(&m->targets.ipv4) == 0 && m->targets.ipv6.count == 0) {
            LOG(0, "FAIL: target IP address list empty\n");
            if (has_target_addresses) {
                LOG(0, " [hint] all addresses were removed by exclusion ranges\n");
            } else {
                LOG(0, " [hint] try something like \"--range 10.0.0.0/8\"\n");
                LOG(0, " [hint] try something like \"--range 192.168.0.100-192.168.0.200\"\n");
            }
            exit(1);
