                ;
            readscan_binary_scanfile(m, start, stop, argv);
        }
        break;
    default:
        break;
    }
    return 0;
}

void main_listscan(struct Masscan *m)
{
    uint64_t i, range, start, end;
    struct BlackRock br;
    unsigned increment = m->shard.of;
    uint64_t seed = m->seed;

    if (m->targets.ports.count == 0) {
        rangelist_add_range(&m->targets.ports, 80, 80);
        massip_optimize(&m->targets);
    }
    {
        u128 c6 = range6list_count(&m->targets.ipv6, NULL);
        range = (uint64_t)(((u128)rangelist_count(&m->targets.ipv4) + c6) * m->targets.count_ports);
    }

infinite:
    blackrock_init(&br, range, seed, m->blackrock_rounds);

    start = m->resume.index + (m->shard.one - 1);
    end = range;
    if (m->resume.count && end > start + m->resume.count)
        end = start + m->resume.count;
    end += (uint64_t)(m->retries * m->max_rate);

    for (i = start; i < end; ) {
        uint64_t x = blackrock_shuffle(&br, i);
        char buf[64];
        unsigned port;
        int is_v6;

        if (x < m->targets.ipv4_index_threshold) {
            uint64_t n4 = rangelist_count(&m->targets.ipv4);
            uint32_t ip = rangelist_pick(&m->targets.ipv4, x % n4);
            port = rangelist_pick(&m->targets.ports, x / n4);
            format_ipv4(buf, sizeof(buf), ip);
            is_v6 = 0;
        } else {
            uint64_t n6 = (uint64_t)range6list_count(&m->targets.ipv6, NULL);
            u128 ip6;
            x -= m->targets.ipv4_index_threshold;
            ip6 = range6list_pick(&m->targets.ipv6, x % n6);
            port = rangelist_pick(&m->targets.ports, x / n6);
            format_ipv6(buf, sizeof(buf), ip6);
            is_v6 = 1;
        }
        if (m->targets.count_ports == 1)
            printf("%s\n", buf);
        else if (is_v6)
            printf("[%s]:%u\n", buf, port);
        else
            printf("%s:%u\n", buf, port);
        i += increment;
    }
    if (m->is_infinite) {
        seed++;
        goto infinite;
    }
}

void main_readrange(struct Masscan *m)
{
    size_t i;
    for (i = 0; i < m->targets.ipv4.count; i++)
        print_range4(stdout, m->targets.ipv4.list[i].begin, m->targets.ipv4.list[i].end);
    for (i = 0; i < m->targets.ipv6.count; i++)
        print_range6(stdout, m->targets.ipv6.list[i].begin, m->targets.ipv6.list[i].end);
}
