#include "masscan.h"
#include "util.h"
#include "blackrock.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>

void main_listscan(struct Masscan *m);
void main_readrange(struct Masscan *m);
int main_selftest(struct Masscan *m);
int main_benchmark(struct Masscan *m);
void readscan_binary_scanfile(struct Masscan *m, int start, int stop, char **argv);
int main_scan(struct Masscan *m);
void pcap_init_messages(void);

void print_version(void)
{
    printf("\n");
    printf("Masscan version 1.3.9-integration ( https://github.com/robertdavidgraham/masscan )\n");
    printf("Compiled on: Jun 12 2026 00:40:26\n");
    printf("Compiler: gcc 11.4.0\n");
    printf("OS: Linux\n");
    printf("CPU: x86 (64 bits)\n");
    printf("GIT version: unknown\n");
}

static uint64_t get_entropy(void)
{
    uint64_t x = 0;
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd >= 0) {
        if (read(fd, &x, sizeof(x)) != sizeof(x))
            x = 0;
        close(fd);
    }
    if (x == 0) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        x = ((uint64_t)ts.tv_sec << 32) ^ (uint64_t)ts.tv_nsec ^ (uint64_t)getpid();
    }
    return x;
}

int main(int argc, char *argv[])
{
    static struct Masscan masscan[1];
    struct Masscan *m = masscan;
    int has_target_addresses = 0;
    int has_target_ports = 0;

    setvbuf(stderr, NULL, _IONBF, 0);
    masscan_init(m);

    masscan_command_line(m, argc, argv);

    if (m->seed == 0)
        m->seed = get_entropy();

    masscan_load_database_files(m);

    pcap_init_messages();

    /* apply excludes */
    {
        has_target_addresses = (m->targets.ipv4.count != 0) || (m->targets.ipv6.count != 0);
        has_target_ports = m->targets.ports.count != 0;
        rangelist_exclude(&m->targets.ipv4, &m->exclude.ipv4);
        range6list_exclude(&m->targets.ipv6, &m->exclude.ipv6);
        rangelist_exclude(&m->targets.ports, &m->exclude.ports);
        massip_optimize(&m->targets);
    }

    /* check range size */
    {
        int overflow = 0;
        u128 c6 = range6list_count(&m->targets.ipv6, &overflow);
        u128 c4 = rangelist_count(&m->targets.ipv4);
        u128 ports = rangelist_count(&m->targets.ports);
        u128 total;
        unsigned bits;
        if (ports == 0) {
            bits = 0;
        } else {
            u128 ips = c4 + c6;
            if (ips < c6 || overflow)
                ips = ~(u128)0;
            if (ips && ports > (~(u128)0) / ips)
                total = ~(u128)0;
            else
                total = ips * ports;
            bits = u128_bitcount(total);
        }
        if (bits > 63) {
            fprintf(stderr, "[-] FAIL: scan range too large, max is 63-bits, requested is %u bits\n", bits);
            fprintf(stderr, "    Hint: scan range is number of IP addresses times number of ports\n");
            fprintf(stderr, "    Hint: IPv6 subnet must be at least /66 \n");
            exit(1);
        }
    }

    switch (m->op) {
    case Operation_Default:
        masscan_usage();
        break;
    case Operation_Scan:
        if (rangelist_count(&m->targets.ipv4) == 0 && m->targets.ipv6.count == 0) {
            LOG(0, "FAIL: target IP address list empty\n");
            if (has_target_addresses) {
                LOG(0, " [hint] all addresses were removed by exclusion ranges\n");
            } else {
                LOG(0, " [hint] try something like \"--range 10.0.0.0/8\"\n");
                LOG(0, " [hint] try something like \"--range 192.168.0.100-192.168.0.200\"\n");
            }
            exit(1);
        }
        if (rangelist_count(&m->targets.ports) == 0) {
            if (has_target_ports) {
                LOG(0, " [hint] all ports were removed by exclusion ranges\n");
            } else {
                LOG(0, "FAIL: no ports were specified\n");
                LOG(0, " [hint] try something like \"-p80,8000-9000\"\n");
                LOG(0, " [hint] try something like \"--ports 0-65535\"\n");
            }
            return 1;
        }
        return main_scan(m);
    case Operation_ListScan:
        main_listscan(m);
        return 0;
    case Operation_List_Adapters:
        fprintf(stderr, "libpcap not loaded\n");
        break;
    case Operation_Selftest:
        return main_selftest(m);
    case Operation_Benchmark:
        return main_benchmark(m);
    case Operation_Echo:
        masscan_echo(m, stdout, 0);
        exit(0);
        break;
    case Operation_EchoAll:
        masscan_echo(m, stdout, 0);
        exit(0);
        break;
    case Operation_EchoCidr:
        masscan_echo_cidr(m, stdout);
        exit(0);
        break;
    case Operation_ReadRange:
        main_readrange(m);
        return 0;
    case Operation_ReadScan:
        {
            int start, stop;
            for (start = 1; start < argc; start++) {
                if (memcmp(argv[start], "--readscan", 10) == 0) {
                    start++;
                    break;
                }
            }
            for (stop = start + 1; stop < argc && argv[stop][0] != '-'; stop++)
                ;
            readscan_binary_scanfile(m, start, stop, argv);
        }
        break;
    default:
        break;
    }
    return 0;
}

void main_listscan(struct Masscan *m)
{
    uint64_t i, range, start, end;
    struct BlackRock br;
    unsigned increment = m->shard.of;
    uint64_t seed = m->seed;

    if (m->targets.ports.count == 0) {
        rangelist_add_range(&m->targets.ports, 80, 80);
        massip_optimize(&m->targets);
    }
    {
        u128 c6 = range6list_count(&m->targets.ipv6, NULL);
        range = (uint64_t)(((u128)rangelist_count(&m->targets.ipv4) + c6) * m->targets.count_ports);
    }

infinite:
    blackrock_init(&br, range, seed, m->blackrock_rounds);

    start = m->resume.index + (m->shard.one - 1);
    end = range;
    if (m->resume.count && end > start + m->resume.count)
        end = start + m->resume.count;
    end += (uint64_t)(m->retries * m->max_rate);

    for (i = start; i < end; ) {
        uint64_t x = blackrock_shuffle(&br, i);
        char buf[64];
        unsigned port;
        int is_v6;

        if (x < m->targets.ipv4_index_threshold) {
            uint64_t n4 = rangelist_count(&m->targets.ipv4);
            uint32_t ip = rangelist_pick(&m->targets.ipv4, x % n4);
            port = rangelist_pick(&m->targets.ports, x / n4);
            format_ipv4(buf, sizeof(buf), ip);
            is_v6 = 0;
        } else {
            uint64_t n6 = (uint64_t)range6list_count(&m->targets.ipv6, NULL);
            u128 ip6;
            x -= m->targets.ipv4_index_threshold;
            ip6 = range6list_pick(&m->targets.ipv6, x % n6);
            port = rangelist_pick(&m->targets.ports, x / n6);
            format_ipv6(buf, sizeof(buf), ip6);
            is_v6 = 1;
        }
        if (m->targets.count_ports == 1)
            printf("%s\n", buf);
        else if (is_v6)
            printf("[%s]:%u\n", buf, port);
        else
            printf("%s:%u\n", buf, port);
        i += increment;
    }
    if (m->is_infinite) {
        seed++;
        goto infinite;
    }
}

void main_readrange(struct Masscan *m)
{
    size_t i;
    for (i = 0; i < m->targets.ipv4.count; i++)
        print_range4(stdout, m->targets.ipv4.list[i].begin, m->targets.ipv4.list[i].end);
    for (i = 0; i < m->targets.ipv6.count; i++)
        print_range6(stdout, m->targets.ipv6.list[i].begin, m->targets.ipv6.list[i].end);
}
EOF
