static int rf_prefix(struct RFParser *p, unsigned max, unsigned *prefix, int allow_empty)
{
    unsigned v = 0, n = 0;
    int c;
    for (;;) {
        c = rf_peek(p);
        if (c < '0' || c > '9')
            break;
