            return rf_error(p, rf_col(p, p->i));
        p->i++;
    }
    if (n == 0 && !allow_empty)
        return rf_error(p, rf_col(p, p->i));
    if (!is_end(c))
        return rf_error(p, rf_col(p, p->i));
