    if (bracketed) {
        if (c == ']') {
            p->i++;
            c = rf_peek(p);
        }
    }
    if (c == '-') {
        u128 b;
        size_t ts;
        int br2 = 0;
        p->i++;
        if (rf_peek(p) == '[') {
            br2 = 1;
            p->i++;
        }
        ts = p->i;
        c = rf_peek(p);
        if (rf_parse_v6(p, ts, 0, br2, &b) != 0)
            return -1;
        if (br2 && rf_peek(p) == ']')
            p->i++;
        c = rf_peek(p);
        if (!is_end(c))
            return rf_error(p, rf_col(p, p->i));
        range6list_add_range(&massip->ipv6, a, b);
        rf_consume_comma(p);
        return 0;
    }
    if (c == '/') {
        unsigned prefix;
        u128 mask;
        p->i++;
        if (rf_prefix(p, 128, &prefix, 0) != 0)
            return -1;
        mask = prefix ? (~(u128)0 << (128 - prefix)) : 0;
        range6list_add_range(&massip->ipv6, a & mask, (a & mask) | ~mask);
        rf_consume_comma(p);
        return 0;
    }
    if (is_end(c)) {
        range6list_add_range(&massip->ipv6, a, a);
        rf_consume_comma(p);
        return 0;
    }
    return rf_error(p, rf_col(p, p->i));
}

static int rf_parse(struct RFParser *p, struct MassIP *massip)
{
    for (;;) {
        int c = rf_peek(p);
        if (c == -1)
            return 0;
        if (c == '\n') {
            p->i++;
            p->line++;
            p->line_start = p->i;
            p->shift = 0;
            continue;
        }
        if (is_ws(c)) {
            p->i++;
            continue;
        }
        if (c == '#' || c == ';' || c == '-' || c == '/') {
            while (p->i < p->len && p->buf[p->i] != '\n')
                p->i++;
            continue;
        }
        if (isdigit(c)) {
            size_t ts = p->i;
            unsigned v = 0, n = 0;
            for (;;) {
                c = rf_peek(p);
                if (c < '0' || c > '9')
                    break;
                v = v * 10 + (unsigned)(c - '0');
                n++;
                if (n > 4)
                    return rf_error(p, rf_col(p, p->i));
                p->i++;
            }
            if (c == '.') {
                uint32_t a;
                if (rf_parse_v4_rest(p, v, n, 0, &a) != 0)
                    return -1;
                c = rf_peek(p);
                if (c == '-') {
                    uint32_t b;
                    p->i++;
                    if (rf_parse_v4_strict(p, &b) != 0)
                        return -1;
                    c = rf_peek(p);
                    if (!is_end(c))
                        return rf_error(p, rf_col(p, p->i));
                    rangelist_add_range(&massip->ipv4, a, b);
                    rf_consume_comma(p);
                } else if (c == '/') {
                    unsigned prefix;
                    uint32_t mask;
                    p->i++;
                    if (rf_prefix(p, 32, &prefix, 1) != 0)
                        return -1;
                    mask = prefix ? (0xFFFFFFFFU << (32 - prefix)) : 0;
                    rangelist_add_range(&massip->ipv4, a & mask, (a & mask) | ~mask);
                    rf_consume_comma(p);
                } else if (is_end(c)) {
                    rangelist_add_range(&massip->ipv4, a, a);
                    rf_consume_comma(p);
                } else
                    return rf_error(p, rf_col(p, p->i));
                continue;
            }
            if (c == ':' || hexv(c) >= 0) {
                u128 a;
                p->shift++;
                if (rf_parse_v6(p, ts, 1, 0, &a) != 0)
                    return -1;
                if (rf_v6_tail(p, massip, a, 0) != 0)
                    return -1;
                continue;
            }
            if (n == 4)
                return rf_error(p, rf_col(p, p->i) + 1);
            return rf_error(p, rf_col(p, p->i));
        }
        if (c == '[') {
            u128 a;
            p->i++;
            if (rf_parse_v6(p, p->i, 0, 1, &a) != 0)
                return -1;
            if (rf_v6_tail(p, massip, a, 1) != 0)
                return -1;
            continue;
        }
        if (c == ':' || hexv(c) >= 0) {
            u128 a;
            if (rf_parse_v6(p, p->i, 0, 0, &a) != 0)
                return -1;
            if (rf_v6_tail(p, massip, a, 0) != 0)
                return -1;
            continue;
        }
        return rf_error(p, rf_col(p, p->i));
    }
}

/* returns 0 ok, 2 parse error (message printed); exits on open failure */
int massip_parse_file(struct MassIP *massip, const char *filename, int *err_line)
{
    FILE *fp;
    char *buf = NULL;
    size_t len = 0, cap = 0;
    struct RFParser p;
    int x;

    (void)err_line;
    fp = fopen(filename, "rb");
    if (fp == NULL) {
        int e = errno;
        fprintf(stderr, "[-] FAIL: parsing IP addresses\n");
        fprintf(stderr, "[-] %s: %s\n", filename, strerror(e));
        exit(1);
    }
    for (;;) {
        size_t n;
        if (len + 65536 > cap) {
            cap = cap * 2 + 65536;
            buf = realloc(buf, cap);
        }
        n = fread(buf + len, 1, cap - len, fp);
        if (n == 0)
            break;
        len += n;
    }
    fclose(fp);

    memset(&p, 0, sizeof(p));
    p.buf = buf;
    p.len = len;
    p.line = 1;
    p.filename = filename;
    x = rf_parse(&p, massip);
    free(buf);
    return x == 0 ? 0 : 2;
}
