/* The scan operation. Packet transmission requires libpcap, which is
 * never available in this build, so this reproduces the initialization
 * sequence up to the point where it fails. */
#include "masscan.h"
#include "util.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
