#include <ifaddrs.h>

static int get_default_interface(char *ifname, size_t sizeof_ifname)
{
    FILE *fp = fopen("/proc/net/route", "r");
    char line[512];
    if (fp == NULL)
        return -1;
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }
    while (fgets(line, sizeof(line), fp)) {
        char name[64];
        unsigned long dest, gw, flags;
        if (sscanf(line, "%63s %lx %lx %lx", name, &dest, &gw, &flags) != 4)
            continue;
        if (dest == 0) {
            snprintf(ifname, sizeof_ifname, "%s", name);
            fclose(fp);
            return 0;
        }
    }
    fclose(fp);
    return -1;
}

static int get_adapter_ipv4(const char *ifname, uint32_t *ip)
{
    int fd;
    struct ifreq ifr;
    int x;

    fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0)
        return -1;
    memset(&ifr, 0, sizeof(ifr));
    ifr.ifr_addr.sa_family = AF_INET;
    snprintf(ifr.ifr_name, IFNAMSIZ, "%s", ifname);
    x = ioctl(fd, SIOCGIFADDR, &ifr);
    if (x < 0) {
        fprintf(stderr, "ERROR:'%s': %s\n", ifname, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    *ip = ntohl(((struct sockaddr_in *)&ifr.ifr_addr)->sin_addr.s_addr);
    return 0;
}

static int get_adapter_ipv6(const char *ifname, u128 *ip)
{
    struct ifaddrs *list = NULL, *p;
    int found = 0;
    if (getifaddrs(&list) != 0)
        return -1;
    for (p = list; p; p = p->ifa_next) {
        if (p->ifa_addr == NULL || p->ifa_addr->sa_family != AF_INET6)
            continue;
        if (strcmp(p->ifa_name, ifname) != 0)
            continue;
        {
            const unsigned char *b = ((struct sockaddr_in6 *)p->ifa_addr)->sin6_addr.s6_addr;
            u128 r = 0;
            int k;
            for (k = 0; k < 16; k++)
                r = (r << 8) | b[k];
            /* skip link-local unless nothing else */
            if ((b[0] == 0xfe) && ((b[1] & 0xc0) == 0x80) && found)
                continue;
            *ip = r;
            found = 1;
        }
    }
    freeifaddrs(list);
    return found ? 0 : -1;
}

int main_scan(struct Masscan *m)
{
    uint64_t count_ips;
    unsigned index;
    unsigned nic_count = m->nic_count ? m->nic_count : 1;

    {
        u128 c6 = range6list_count(&m->targets.ipv6, NULL);
        u128 c = (u128)rangelist_count(&m->targets.ipv4) + c6;
        count_ips = (c > 0xFFFFFFFFFFFFFFFFULL) ? 0xFFFFFFFFFFFFFFFFULL : (uint64_t)c;
    }
    if (count_ips > 1000000000ULL && rangelist_count(&m->exclude.ipv4) == 0) {
        LOG(0, "FAIL: range too big, need confirmation\n");
        LOG(0, " [hint] to prevent accidents, at least one --exclude must be specified\n");
        LOG(0, " [hint] use \"--exclude 255.255.255.255\" as a simple confirmation\n");
        exit(1);
    }

    for (index = 0; index < nic_count; index++) {
        struct NicConf *nic = &m->nic[index];
        char ifname[256];
        char buf[64];

        if (nic->ifname[0])
            snprintf(ifname, sizeof(ifname), "%s", nic->ifname);
        else {
            if (get_default_interface(ifname, sizeof(ifname)) != 0) {
                LOG(0, "[-] FAIL: could not determine default interface\n");
                LOG(0, "    [hint] try \"--interface ethX\"\n");
                exit(1);
            }
        }
        LOG(1, "[+] interface = %s\n", ifname);

        if (!m->is_offline) {
            LOG(2, "[+] if(%s): pcap: %s\n", ifname, "stub/0.0");
            LOG(2, "[+] if(%s): opening...\n", ifname);
            LOG(0, "FAIL:%s: can't open adapter: libpcap not loaded\n", ifname);
            LOG(0, "[-] if:%s:init: failed\n", ifname);
            exit(1);
        }

        LOG(1, "[+] interface-type = %u\n", 0);
        LOG(1, "[+] source-mac = none\n");

        if (m->targets.ipv4.count) {
            uint32_t ip = 0;
            if (nic->has_src_ipv4 && (nic->src_ipv4_first || nic->src_ipv4_last))
                ip = nic->src_ipv4_first;
            else if (get_adapter_ipv4(ifname, &ip) != 0 || ip == 0) {
                LOG(0, "[-] FAIL: failed to detect IP of interface \"%s\"\n", ifname);
                LOG(0, "    [hint] did you spell the name correctly?\n");
                LOG(0, "    [hint] if it has no IP address, manually set with something like \"--source-ip 198.51.100.17\"\n");
                exit(1);
            }
            format_ipv4(buf, sizeof(buf), ip);
            LOG(1, "[+] source-ip = %s\n", buf);
        }
        if (m->targets.ipv6.count) {
            u128 ip6 = 0;
            if (nic->has_src_ipv6)
                ip6 = nic->src_ipv6_first;
            else if (get_adapter_ipv6(ifname, &ip6) != 0) {
                LOG(0, "[-] FAIL: failed to detect IPv6 address of interface \"%s\"\n", ifname);
                LOG(0, "    [hint] did you spell the name correctly?\n");
                LOG(0, "    [hint] if it has no IP address, manually set with something like \"--source-ip 2001:3b8::1234\"\n");
                exit(1);
            }
            format_ipv6(buf, sizeof(buf), ip6);
            LOG(1, "[+] source-ip = [%s]\n", buf);
            LOG(1, "[+] router-mac-ipv6 = 66-55-44-33-22-11\n");
        }
        LOG(2, "[+] if(%s): initialization done.\n", ifname);
        LOG(0, "[-] FAILED: bad packet template\n");
        exit(1);
    }
    return 1;
}
