/* Reading binary scan files (--readscan) and writing results in the
 * various output formats. */
#include "masscan.h"
#include "util.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <ctype.h>

#include "services.inc"
#include "oproto.inc"

enum { ST_OPEN = 1, ST_CLOSED = 2, ST_ARP = 3 };

struct Rec {
    int is_banner;
    int status;
    uint32_t timestamp;
    int is_v6;
    uint32_t ipv4;
    u128 ipv6;
    unsigned ip_proto;
    unsigned port;
    unsigned reason;
    unsigned ttl;
    unsigned app;
    const unsigned char *banner;
    size_t banner_len;
};

struct Out {
    struct Masscan *m;
    FILE *fp;
    int is_open;
    int format;
    unsigned count;
    uint32_t start_ts;
    time_t open_time;
    unsigned up, down;
};

/* ---------------------------------------------------------- names */

static const char *proto_name(unsigned p)
{
    switch (p) {
    case 0: return "arp";
    case 1: return "icmp";
    case 6: return "tcp";
    case 17: return "udp";
    case 132: return "sctp";
    default: return "err";
    }
}

static const char *status_name(int s)
{
    switch (s) {
    case ST_OPEN: return "open";
    case ST_CLOSED: return "closed";
    case ST_ARP: return "arp";
    default: return "unknown";
    }
}

static const char *app_names[] = {
    "unknown", "unknown", "ssh", "ssh", "http", "ftp", "dns-ver", "snmp", "nbtstat", "ssl",
    "smb", "smtp", "pop", "imap", "zeroaccess", "X509", "X509CA", "title", "html", "ntp",
    "vuln", "heartbleed", "ticketbleed", "vnc", "safe", "memcached", "scripting", "versioning", "coap", "telnet",
    "rdp", "http.server", "minecraft", "vnc", "vnc-info", "isakmp", "error"
};

static const char *app_name(unsigned app, char *tmp, size_t n)
{
    if (app < sizeof(app_names) / sizeof(app_names[0]))
        return app_names[app];
    snprintf(tmp, n, "(%u)", app);
    return tmp;
}

static void reason_string(unsigned r, char *buf, size_t n)
{
    static const char *flags[] = {"fin", "syn", "rst", "psh", "ack", "urg", "ece", "cwr"};
    size_t len = 0;
    int i;
    buf[0] = '\0';
    if (r == 0) {
        snprintf(buf, n, "none");
        return;
    }
    for (i = 0; i < 8; i++) {
        if (r & (1u << i))
            len += snprintf(buf + len, n - len, "%s%s", len ? "-" : "", flags[i]);
    }
}

static const char *tcp_service_name(unsigned port)
{
    size_t i;
    for (i = 0; tcp_services[i].name; i++)
        if (tcp_services[i].port == port)
            return tcp_services[i].name;
    return "unknown";
}

static const char *udp_service_name(unsigned port)
{
    size_t i;
    for (i = 0; udp_services[i].name; i++)
        if (udp_services[i].port == port)
            return udp_services[i].name;
    return "unknown";
}

static const char *service_name(unsigned ip_proto, unsigned port)
{
    switch (ip_proto) {
    case 6: return tcp_service_name(port);
    case 17: return udp_service_name(port);
    case 132: return "sctp";
    default: return oproto_names[ip_proto & 0xFF];
    }
}

static void fmt_ip(const struct Rec *r, char *buf, size_t n)
{
    if (r->is_v6)
        format_ipv6(buf, n, r->ipv6);
    else
        format_ipv4(buf, n, r->ipv4);
}

/* escape for text/xml formats */
static char *escape_banner(const unsigned char *s, size_t len)
{
    char *out = malloc(len * 4 + 1);
    size_t i, d = 0;
    for (i = 0; i < len; i++) {
        unsigned c = s[i];
        if (c < 0x20 || c >= 0x7f || c == '"' || c == '&' || c == '\'' || c == '<' || c == '>' || c == '\\') {
            static const char hex[] = "0123456789abcdef";
            out[d++] = '\\';
            out[d++] = 'x';
            out[d++] = hex[c >> 4];
            out[d++] = hex[c & 0xF];
        } else
            out[d++] = (char)c;
    }
    out[d] = '\0';
    return out;
}

static char *escape_json(const unsigned char *s, size_t len)
{
    char *out = malloc(len * 6 + 1);
    size_t i, d = 0;
    for (i = 0; i < len; i++) {
        unsigned c = s[i];
        if (c < 0x20 || c >= 0x7f || c == '"' || c == '&' || c == '\'' || c == '<' || c == '>' || c == '\\') {
            d += (size_t)sprintf(out + d, "\\u%04x", c);
        } else
            out[d++] = (char)c;
    }
    out[d] = '\0';
    return out;
}

/* ---------------------------------------------------------- output */

static void write_ports_scanned(struct Out *o)
{
    struct RangeList *ports = &o->m->targets.ports;
    size_t i;
    unsigned cat;
    static const char *labels[] = {"TCP", "UDP", "SCTP", "PROTOCOLS"};
    fprintf(o->fp, "# Ports scanned:");
    for (cat = 0; cat < 4; cat++) {
        uint64_t count = 0;
        uint32_t lo = cat * 65536, hi = (cat < 3) ? (cat + 1) * 65536 : 0xFFFFFFFF;
        if (cat == 3) lo = Templ_Oproto_first;
        for (i = 0; i < ports->count; i++) {
            if (ports->list[i].begin >= lo && ports->list[i].begin < hi && !(cat == 2 && ports->list[i].begin >= Templ_ICMP_echo))
                count += (uint64_t)ports->list[i].end - ports->list[i].begin + 1;
        }
        fprintf(o->fp, "%s%s(%u;", cat ? " " : " ", labels[cat], (unsigned)count);
        for (i = 0; i < ports->count; i++) {
            uint32_t b = ports->list[i].begin;
            if (b >= lo && b < hi && (cat != 2 || b < Templ_ICMP_echo) && (cat != 3 || b >= Templ_Oproto_first))
                fprintf(o->fp, "%u-%u%s", b, ports->list[i].end, (i + 1 < ports->count) ? "," : "");
        }
        fprintf(o->fp, ")");
    }
    fprintf(o->fp, "\n");
}

static void format_ctime(time_t t, char *buf, size_t n)
{
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, n, "%a %b %e %H:%M:%S %Y", &tm);
}

static void out_open(struct Out *o, const struct Rec *r)
{
    const char *fn = o->m->output.filename;
    if (o->is_open)
        return;
    o->is_open = 1;
    o->start_ts = r->timestamp;
    o->open_time = time(0);
    if (fn[0] == '\0' || strcmp(fn, "-") == 0 || o->format == Output_Interactive || o->format == 0)
        o->fp = stdout;
    else {
        o->fp = fopen(fn, o->m->output.is_append ? "a" : "w");
        if (o->fp == NULL) {
            fprintf(stderr, "[-] FAIL: could not open file %s for %s\n", fn, o->m->output.is_append ? "appending" : "writing");
            perror(fn);
            exit(1);
        }
    }
    switch (o->format) {
    case Output_List:
    case Output_Unicornscan:
        fprintf(o->fp, "#masscan\n");
        break;
    case Output_JSON:
        fprintf(o->fp, "[\n");
        break;
    case Output_XML:
        fprintf(o->fp, "<?xml version=\"1.0\"?>\r\n");
        fprintf(o->fp, "<!-- masscan v1.0 scan -->\r\n");
        if (o->m->output.stylesheet && o->m->output.stylesheet[0])
            fprintf(o->fp, "<?xml-stylesheet href=\"%s\" type=\"text/xsl\"?>\r\n", o->m->output.stylesheet);
        fprintf(o->fp, "<nmaprun scanner=\"%s\" start=\"%u\" version=\"%s\"  xmloutputversion=\"%s\">\r\n",
                "masscan", (unsigned)o->open_time, "1.0-BETA", "1.03");
        fprintf(o->fp, "<scaninfo type=\"%s\" protocol=\"%s\" />\r\n", "syn", "tcp");
        break;
    case Output_Grepable:
        {
            char tbuf[64];
            format_ctime((time_t)o->start_ts, tbuf, sizeof(tbuf));
            fprintf(o->fp, "# Masscan 1.3.9-integration scan initiated %s\n", tbuf);
            write_ports_scanned(o);
        }
        break;
    case Output_Binary:
        {
            char first[99];
            memset(first, 0, sizeof(first));
            snprintf(first, sizeof(first), "masscan/1.1\ns:%u\n", (unsigned)o->start_ts);
            fwrite(first, 1, sizeof(first), o->fp);
        }
        break;
    default:
        break;
    }
}

static void out_close(struct Out *o)
{
    if (!o->is_open)
        return;
    switch (o->format) {
    case Output_List:
    case Output_Unicornscan:
        fprintf(o->fp, "# end\n");
        break;
    case Output_JSON:
        fprintf(o->fp, "]\n");
        break;
    case Output_XML:
        {
            time_t now = time(0);
            char tbuf[64];
            struct tm tm;
            localtime_r(&now, &tm);
            strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(o->fp, "<runstats>\r\n");
            fprintf(o->fp, "<finished time=\"%u\" timestr=\"%s\" elapsed=\"%u\" />\r\n",
                    (unsigned)now, tbuf, (unsigned)(now - o->open_time));
            fprintf(o->fp, "<hosts up=\"%u\" down=\"%u\" total=\"%u\" />\r\n", o->up, o->down, o->up + o->down);
            fprintf(o->fp, "</runstats>\r\n");
            fprintf(o->fp, "</nmaprun>\r\n");
        }
        break;
    case Output_Grepable:
        {
            char tbuf[64];
            format_ctime(time(0), tbuf, sizeof(tbuf));
            fprintf(o->fp, "# Masscan done at %s\n", tbuf);
        }
        break;
    case Output_Certs:
        fprintf(o->fp, "{finished: 1}\n");
        break;
    case Output_Binary:
        {
            char last[99];
            memset(last, 0, sizeof(last));
            snprintf(last, sizeof(last), "masscan/1.1");
            fwrite(last, 1, sizeof(last), o->fp);
        }
        break;
    default:
        break;
    }
    fflush(o->fp);
    if (o->fp != stdout)
        fclose(o->fp);
}

static void put32(unsigned char *b, uint32_t x)
{
    b[0] = (unsigned char)(x >> 24); b[1] = (unsigned char)(x >> 16);
    b[2] = (unsigned char)(x >> 8); b[3] = (unsigned char)x;
}

static void write_record_header(FILE *fp, unsigned type, size_t len)
{
    unsigned char hdr[4];
    size_t n = 0;
    hdr[n++] = (unsigned char)type;
    if (len < 128)
        hdr[n++] = (unsigned char)len;
    else if (len < 16384) {
        hdr[n++] = (unsigned char)(0x80 | (len >> 7));
        hdr[n++] = (unsigned char)(len & 0x7F);
    } else {
        hdr[n++] = (unsigned char)(0x80 | (len >> 14));
        hdr[n++] = (unsigned char)(0x80 | ((len >> 7) & 0x7F));
        hdr[n++] = (unsigned char)(len & 0x7F);
    }
    fwrite(hdr, 1, n, fp);
}

static void out_status(struct Out *o, const struct Rec *r)
{
    char ip[64], reason[64];
    FILE *fp;

    if (r->status == ST_OPEN && !o->m->output.is_show_open)
        return;
    if (r->status == ST_CLOSED && !o->m->output.is_show_closed)
        return;
    if (o->format == Output_None || o->format == Output_Certs)
        return;
    out_open(o, r);
    fp = o->fp;
    fmt_ip(r, ip, sizeof(ip));
    reason_string(r->reason, reason, sizeof(reason));

    if (r->ip_proto == 6) {
        if (r->status == ST_OPEN) o->up++;
        else if (r->status == ST_CLOSED) o->down++;
    }

    switch (o->format) {
    case Output_Interactive:
    case 0:
        {
            int count;
            if (r->ip_proto == 0)
                count = fprintf(fp, "Discovered %s port %u/%s on %s (00:00:00:00:00:00)",
                                status_name(r->status), r->port, proto_name(r->ip_proto), ip);
            else
                count = fprintf(fp, "Discovered %s port %u/%s on %s",
                                status_name(r->status), r->port, proto_name(r->ip_proto), ip);
            if (count < 80)
                fprintf(fp, "%.*s", 79 - count,
                        "                                                                                ");
            fprintf(fp, "\n");
        }
        break;
    case Output_List:
        fprintf(fp, "%s %s %u %s %u\n", status_name(r->status), proto_name(r->ip_proto), r->port, ip, r->timestamp);
        break;
    case Output_JSON:
        if (o->count++)
            fprintf(fp, ",\n");
        fprintf(fp, "{ ");
        fprintf(fp, "  \"ip\": \"%s\", ", ip);
        fprintf(fp, "  \"timestamp\": \"%u\", \"ports\": [ {\"port\": %u, \"proto\": \"%s\", \"status\": \"%s\", \"reason\": \"%s\", \"ttl\": %u} ] }\n",
                r->timestamp, r->port, proto_name(r->ip_proto), status_name(r->status), reason, r->ttl);
        break;
    case Output_NDJSON:
        fprintf(fp, "{\"ip\":\"%s\",\"timestamp\":\"%u\",\"port\":%u,\"proto\":\"%s\",\"rec_type\":\"status\",\"data\":{\"status\":\"%s\",\"reason\":\"%s\",\"ttl\":%u}}\n",
                ip, r->timestamp, r->port, proto_name(r->ip_proto), status_name(r->status), reason, r->ttl);
        break;
    case Output_XML:
        fprintf(fp, "<host endtime=\"%u\"><address addr=\"%s\" addrtype=\"%s\"/><ports><port protocol=\"%s\" portid=\"%u\"><state state=\"%s\" reason=\"%s\" reason_ttl=\"%u\"/></port></ports></host>\r\n",
                r->timestamp, ip, "ipv4", proto_name(r->ip_proto), r->port, status_name(r->status), reason, r->ttl);
        break;
    case Output_Grepable:
        fprintf(fp, "Timestamp: %u\tHost: %s ()\tPorts: %u/%s/%s//%s//\n",
                r->timestamp, ip, r->port, status_name(r->status), proto_name(r->ip_proto),
                service_name(r->ip_proto, r->port));
        break;
    case Output_Unicornscan:
        if (r->ip_proto == 6)
            fprintf(fp, "TCP %s\t%16s[%5u]\t\tfrom %s  ttl %u \n",
                    status_name(r->status), tcp_service_name(r->port), r->port, ip, r->ttl);
        else
            fprintf(fp, "Host: %s ()\tPorts: %u/%s/%s////\n", ip, r->port, status_name(r->status), proto_name(r->ip_proto));
        break;
    case Output_Hostonly:
        fprintf(fp, "%s\n", ip);
        break;
    case Output_Binary:
        {
            unsigned char b[64];
            if (r->is_v6) {
                int k;
                put32(b, r->timestamp);
                b[4] = (unsigned char)r->ip_proto;
                b[5] = (unsigned char)(r->port >> 8);
                b[6] = (unsigned char)r->port;
                b[7] = (unsigned char)r->reason;
                b[8] = (unsigned char)r->ttl;
                b[9] = 6;
                for (k = 0; k < 16; k++)
                    b[10 + k] = (unsigned char)(r->ipv6 >> (120 - 8 * k));
                write_record_header(fp, r->status == ST_CLOSED ? 11 : 10, 26);
                fwrite(b, 1, 26, fp);
            } else {
                put32(b, r->timestamp);
                put32(b + 4, r->ipv4);
                b[8] = (unsigned char)r->ip_proto;
                b[9] = (unsigned char)(r->port >> 8);
                b[10] = (unsigned char)r->port;
                b[11] = (unsigned char)r->reason;
                b[12] = (unsigned char)r->ttl;
                write_record_header(fp, r->status == ST_CLOSED ? 7 : 6, 13);
                fwrite(b, 1, 13, fp);
            }
        }
        break;
    default:
        break;
    }
}

static void out_banner(struct Out *o, const struct Rec *r)
{
    char ip[64], tmp[32];
    FILE *fp;
    const char *app;

    if (o->format == Output_None)
        return;
    out_open(o, r);
    fp = o->fp;
    fmt_ip(r, ip, sizeof(ip));
    app = app_name(r->app, tmp, sizeof(tmp));

    switch (o->format) {
    case Output_Interactive:
    case 0:
        {
            char *esc = escape_banner(r->banner, r->banner_len);
            int count = fprintf(fp, "Banner on port %u/%s on %s: [%s] %s", r->port, proto_name(r->ip_proto), ip, app, esc);
            if (count < 80)
                fprintf(fp, "%.*s", 79 - count,
                        "                                                                                ");
            fprintf(fp, "\n");
            free(esc);
        }
        break;
    case Output_List:
        {
            char *esc = escape_banner(r->banner, r->banner_len);
            fprintf(fp, "%s %s %u %s %u %s %s\n", "banner", proto_name(r->ip_proto), r->port, ip, r->timestamp, app, esc);
            free(esc);
        }
        break;
    case Output_JSON:
        {
            char *esc = escape_json(r->banner, r->banner_len);
            if (o->count++)
                fprintf(fp, ",\n");
            fprintf(fp, "{ ");
            fprintf(fp, "  \"ip\": \"%s\", ", ip);
            fprintf(fp, "  \"timestamp\": \"%u\", \"ports\": [ {\"port\": %u, \"proto\": \"%s\", \"service\": {\"name\": \"%s\", \"banner\": \"%s\"} } ] }\n",
                    r->timestamp, r->port, proto_name(r->ip_proto), app, esc);
            free(esc);
        }
        break;
    case Output_NDJSON:
        {
            char *esc = escape_json(r->banner, r->banner_len);
            fprintf(fp, "{\"ip\":\"%s\",\"timestamp\":\"%u\",\"port\":%u,\"proto\":\"%s\",\"rec_type\":\"banner\",\"data\":{\"service_name\":\"%s\",\"banner\":\"%s\"}}\n",
                    ip, r->timestamp, r->port, proto_name(r->ip_proto), app, esc);
            free(esc);
        }
        break;
    case Output_XML:
        {
            char *esc = escape_banner(r->banner, r->banner_len);
            fprintf(fp, "<host endtime=\"%u\"><address addr=\"%s\" addrtype=\"%s\"/><ports><port protocol=\"%s\" portid=\"%u\"><state state=\"open\" reason=\"%s\" reason_ttl=\"%u\" /><service name=\"%s\" banner=\"%s\"></service></port></ports></host>\r\n",
                    r->timestamp, ip, "ipv4", proto_name(r->ip_proto), r->port, "response", r->ttl, app, esc);
            free(esc);
        }
        break;
    case Output_Grepable:
        {
            char *esc = escape_banner(r->banner, r->banner_len);
            fprintf(fp, "Host: %s ()\tPort: %u\tService: %s\tBanner: %s\n", ip, r->port, app, esc);
            free(esc);
        }
        break;
    case Output_Hostonly:
        fprintf(fp, "%s\n", ip);
        break;
    case Output_Certs:
        fprintf(fp, "-----BEGIN CERTIFICATE-----\n");
        fwrite(r->banner, 1, r->banner_len, fp);
        fprintf(fp, "\n-----END CERTIFICATE-----\n");
        break;
    case Output_Binary:
        {
            size_t n;
            unsigned char *b;
            if (r->is_v6) {
                int k;
                n = 26 + r->banner_len;
                b = malloc(n + 1);
                put32(b, r->timestamp);
                b[4] = (unsigned char)r->ip_proto;
                b[5] = (unsigned char)(r->port >> 8);
                b[6] = (unsigned char)r->port;
                b[7] = (unsigned char)(r->app >> 8);
                b[8] = (unsigned char)r->app;
                b[9] = (unsigned char)r->ttl;
                b[10] = 6;
                for (k = 0; k < 16; k++)
                    b[11 + k] = (unsigned char)(r->ipv6 >> (120 - 8 * k));
                n = 27 + r->banner_len;
                b = realloc(b, n + 1);
                memcpy(b + 27, r->banner, r->banner_len);
                write_record_header(fp, 13, n);
            } else {
                n = 14 + r->banner_len;
                b = malloc(n + 1);
                put32(b, r->timestamp);
                put32(b + 4, r->ipv4);
                b[8] = (unsigned char)r->ip_proto;
                b[9] = (unsigned char)(r->port >> 8);
                b[10] = (unsigned char)r->port;
                b[11] = (unsigned char)(r->app >> 8);
                b[12] = (unsigned char)r->app;
                b[13] = (unsigned char)r->ttl;
                memcpy(b + 14, r->banner, r->banner_len);
                write_record_header(fp, 9, n);
            }
            fwrite(b, 1, n, fp);
            free(b);
        }
        break;
    default:
        break;
    }
}

/* ---------------------------------------------------------- reader */

static uint32_t get32(const unsigned char *b)
{
    return ((uint32_t)b[0] << 24) | ((uint32_t)b[1] << 16) | ((uint32_t)b[2] << 8) | b[3];
}

static u128 get128(const unsigned char *b)
{
    u128 r = 0;
    int k;
    for (k = 0; k < 16; k++)
        r = (r << 8) | b[k];
    return r;
}

static int filter_pass(struct Masscan *m, const struct Rec *r)
{
    if (m->targets.ipv4.count) {
        if (r->is_v6)
            return 0;
        if (!rangelist_is_contains(&m->targets.ipv4, r->ipv4))
            return 0;
    }
    if (m->targets.ports.count) {
        if (!rangelist_is_contains(&m->targets.ports, r->port))
            return 0;
    }
    return 1;
}

static void handle(struct Out *o, struct Rec *r)
{
    if (!filter_pass(o->m, r))
        return;
    if (r->is_banner)
        out_banner(o, r);
    else
        out_status(o, r);
}

static void parse_file(struct Out *o, const char *filename)
{
    FILE *fp;
    unsigned char hdr[99];
    unsigned char *buf;
    size_t bufsize = 65536 * 4;

    fp = fopen(filename, "rb");
    if (fp == NULL) {
        int e = errno;
        fprintf(stderr, "[-] FAIL: --readscan\n");
        fprintf(stderr, "[-] %s: %s\n", filename ? filename : "(null)", strerror(e));
        return;
    }
    fprintf(stderr, "[+] --readscan %s\n", filename);
    errno = 0;
    if (fread(hdr, 1, sizeof(hdr), fp) != sizeof(hdr)) {
        int e = errno;
        fprintf(stderr, "[-] %s: %s\n", filename, strerror(e));
        fclose(fp);
        return;
    }
    if (memcmp(hdr, "masscan/1.1", 11) != 0) {
        fprintf(stderr, "[-] %s: unknown file format (expeced \"masscan/1.1\")\n", filename);
        fclose(fp);
        return;
    }
    buf = malloc(bufsize + 16);
    for (;;) {
        int c = fgetc(fp);
        unsigned type;
        size_t length;
        size_t got;
        struct Rec r;

        if (c == EOF)
            break;
        type = (unsigned)c;
        c = fgetc(fp);
        if (c == EOF)
            break;
        length = (size_t)c;
        if (length & 0x80) {
            length &= 0x7F;
            for (;;) {
                c = fgetc(fp);
                if (c == EOF)
                    goto end;
                length = (length << 7) | ((size_t)c & 0x7F);
                if (!(c & 0x80))
                    break;
            }
        }
        if (length > bufsize)
            break;
        got = fread(buf, 1, length, fp);
        if (got != length)
            break;
        if (type == 4) {
            int x = fgetc(fp);
            if (x == EOF) {
                LOG(0, "[-] read() error\n");
                exit(1);
            }
            buf[length] = (unsigned char)x;
            length++;
        }

        memset(&r, 0, sizeof(r));
        switch (type) {
        case 1: case 2:
            if (length < 12) break;
            r.status = (type == 1) ? ST_OPEN : ST_CLOSED;
            r.timestamp = get32(buf);
            r.ipv4 = get32(buf + 4);
            r.ip_proto = 6;
            r.port = ((unsigned)buf[8] << 8) | buf[9];
            r.reason = buf[10];
            r.ttl = buf[11];
            handle(o, &r);
            break;
        case 3:
            if (length < 12) break;
            r.is_banner = 1;
            r.timestamp = get32(buf);
            r.ipv4 = get32(buf + 4);
            r.ip_proto = 6;
            r.port = ((unsigned)buf[8] << 8) | buf[9];
            r.app = ((unsigned)buf[10] << 8) | buf[11];
            r.banner = buf + 12;
            r.banner_len = length - 12;
            handle(o, &r);
            break;
        case 4: case 5:
            if (length < 13) break;
            r.is_banner = 1;
            r.timestamp = get32(buf);
            r.ipv4 = get32(buf + 4);
            r.ip_proto = buf[8];
            r.port = ((unsigned)buf[9] << 8) | buf[10];
            r.app = ((unsigned)buf[11] << 8) | buf[12];
            r.banner = buf + 13;
            r.banner_len = length - 13;
            handle(o, &r);
            break;
        case 6: case 7:
            if (length < 13) break;
            r.status = (type == 6) ? ST_OPEN : ST_CLOSED;
            r.timestamp = get32(buf);
            r.ipv4 = get32(buf + 4);
            r.ip_proto = buf[8];
            r.port = ((unsigned)buf[9] << 8) | buf[10];
            r.reason = buf[11];
            r.ttl = buf[12];
            handle(o, &r);
            break;
        case 9:
            if (length < 14) break;
            r.is_banner = 1;
            r.timestamp = get32(buf);
            r.ipv4 = get32(buf + 4);
            r.ip_proto = buf[8];
            r.port = ((unsigned)buf[9] << 8) | buf[10];
            r.app = ((unsigned)buf[11] << 8) | buf[12];
            r.ttl = buf[13];
            r.banner = buf + 14;
            r.banner_len = length - 14;
            handle(o, &r);
            break;
        case 10: case 11:
            if (length < 26 || buf[9] != 6) {
                fprintf(stderr, "[-] corrupt record\n");
                break;
            }
            r.status = (type == 10) ? ST_OPEN : ST_CLOSED;
            r.timestamp = get32(buf);
            r.ip_proto = buf[4];
            r.port = ((unsigned)buf[5] << 8) | buf[6];
            r.reason = buf[7];
            r.ttl = buf[8];
            r.is_v6 = 1;
            r.ipv6 = get128(buf + 10);
            handle(o, &r);
            break;
        case 13:
            if (length < 27 || buf[10] != 6) {
                fprintf(stderr, "[-] corrupt record\n");
                break;
            }
            r.is_banner = 1;
            r.timestamp = get32(buf);
            r.ip_proto = buf[4];
            r.port = ((unsigned)buf[5] << 8) | buf[6];
            r.app = ((unsigned)buf[7] << 8) | buf[8];
            r.ttl = buf[9];
            r.is_v6 = 1;
            r.ipv6 = get128(buf + 11);
            r.banner = buf + 27;
            r.banner_len = length - 27;
            handle(o, &r);
            break;
        case 'm':
            break;
        default:
            fprintf(stderr, "[-] file corrupt: unknown type %u\n", type);
            goto end;
        }
    }
end:
    free(buf);
    fclose(fp);
}

void readscan_binary_scanfile(struct Masscan *m, int start, int stop, char **argv)
{
    struct Out o;
    int i;

    memset(&o, 0, sizeof(o));
    o.m = m;
    o.format = m->output.format;

    for (i = start; i < stop; i++)
        parse_file(&o, argv[i]);
    out_close(&o);
}
