static int get_next_line(FILE *fp, unsigned *line_number, char *line, size_t sizeof_line)
{
    if (line[0] != '\0')
        return 1;
    for (;;) {
        if (fgets(line, (int)sizeof_line, fp) == NULL) {
            line[0] = '\0';
            return 0;
        }
        (*line_number)++;
        trim_str(line, sizeof_line);
        if (line[0] == '#')
            continue;
        if (line[0] == '\0')
            continue;
        return 1;
