}

static void remove_prefix(char *line, size_t n)
{
    size_t len = strlen(line);
    if (n > len) n = len;
    memmove(line, line + n, len - n + 1);
}

/* parse a C string at start of line (line[0]=='"'), removing it */
static void consume_c_string(char *line)
{
    size_t i = 1;
    while (line[i] && line[i] != '"') {
        if (line[i] == '\\' && line[i+1])
            i += 2;
        else
            i++;
    }
    if (line[i] == '"')
        i++;
    remove_prefix(line, i);
}

static void load_nmap_payloads(FILE *fp, const char *filename)
{
    char line[16384];
    unsigned line_number = 0;

    line[0] = '\0';
    for (;;) {
        unsigned is_error = 0;
        const char *p;
        struct RangeList ports = {0};

        if (!get_next_line(fp, &line_number, line, sizeof(line)))
            break;

        if (memcmp(line, "udp", 3) != 0) {
            fprintf(stderr, "%s:%u: syntax error, expected \"udp\".\n", filename, line_number);
            goto end;
        }
        remove_prefix(line, 3);
        trim_str(line, sizeof(line));

        p = rangelist_parse_ports(&ports, line, &is_error, 0);
        if (is_error) {
            fprintf(stderr, "%s:%u: syntax error, expected ports\n", filename, line_number);
            rangelist_free(&ports);
            goto end;
        }
        memmove(line, p, strlen(p) + 1);
        trim_str(line, sizeof(line));

        for (;;) {
            trim_str(line, sizeof(line));
            if (!get_next_line(fp, &line_number, line, sizeof(line)))
                break;
            if (line[0] != '"')
                break;
            consume_c_string(line);
        }

        if (memcmp(line, "source", 6) == 0) {
            remove_prefix(line, 6);
            trim_str(line, sizeof(line));
            if (!isdigit(line[0] & 0xFF)) {
                fprintf(stderr, "%s:%u: expected source port\n", filename, line_number);
