    }
end:
    ;
}

/* ------------------------------------------------------------ service probes */

static void load_service_probes(FILE *fp, const char *filename)
{
    char line[65536];
    unsigned line_number = 0;
    int have_probe = 0;
    static const char *directives[] = {"Probe", "match", "softmatch", "ports", "sslports",
        "totalwaitms", "tcpwrappedms", "rarity", "fallback", "Exclude", 0};

    while (fgets(line, sizeof(line), fp)) {
        size_t i, n;
        int k, found = -1;
        char tok[256];

        line_number++;
        /* strip trailing newline */
        n = strlen(line);
        while (n && (line[n-1] == '\n' || line[n-1] == '\r'))
            line[--n] = '\0';
        i = 0;
        while (line[i] && isspace(line[i] & 0xFF))
            i++;
        if (line[i] == '\0' || line[i] == '#')
            continue;
        n = 0;
        while (line[i + n] && !isspace(line[i + n] & 0xFF) && n < sizeof(tok) - 2)
            n++;
        memcpy(tok, line + i, n);
        tok[n] = '\0';
        for (k = 0; directives[k]; k++)
            if (strcmp(tok, directives[k]) == 0)
                found = k;
        if (found < 0) {
            size_t tl = n;
            if (line[i + n] && isspace(line[i + n] & 0xFF)) {
                tok[n] = line[i + n];
                tok[n + 1] = '\0';
                tl++;
            }
            fprintf(stderr, "%s:%u:%u: unknown type: '%s'\n", filename, line_number, (unsigned)tl, tok);
            continue;
        }
        if (found == 9) /* Exclude */
            continue;
        if (found == 0) {
            const char *rest = line + i + n;
            while (*rest && isspace(*rest & 0xFF))
                rest++;
            if (strlen(rest) < 4) {
                fprintf(stderr, "%s:%u:%u: line too short\n", filename, line_number, (unsigned)(i + n + 1));
                continue;
            }
            if (memcmp(rest, "TCP", 3) != 0 && memcmp(rest, "UDP", 3) != 0) {
                fprintf(stderr, "%s:%u:%u: unknown protocol\n", filename, line_number, (unsigned)(i + n + 1));
                continue;
            }
            have_probe = 1;
            continue;
        }
        if (!have_probe) {
            fprintf(stderr, "%s:%u:%u: 'directive only valid after a 'Probe'\n", filename, line_number, (unsigned)(i + n + 1));
