static int udp_port_has_default_payload(unsigned port)
{
    return port == 53;
}

int pcap_payloads_read(struct Masscan *m, const char *filename)
{
    FILE *fp;
    unsigned char hdr[24];
    size_t n;
    int swap = 0;
    unsigned linktype;

    (void)m;
    fp = fopen(filename, "rb");
    if (fp == NULL) {
        int e = errno;
        fprintf(stderr, "%s: could not open capture file\n", filename);
        fprintf(stderr, "%s: %s\n", filename, strerror(e));
        fprintf(stderr, "payloads: can't read from file '%s'\n", filename);
        return -1;
    }
    n = fread(hdr, 1, sizeof(hdr), fp);
    if (n < 24) {
        if (n == 0) {
            fprintf(stderr, "%s: could not read PCAP header\n", filename);
            fprintf(stderr, "%s: %s\n", filename, strerror(ENOENT));
        } else
            fprintf(stderr, "%s: file too short\n", filename);
        fprintf(stderr, "payloads: can't read from file '%s'\n", filename);
        fclose(fp);
        return -1;
    }
