        uint32_t magic = (uint32_t)hdr[0] | ((uint32_t)hdr[1] << 8) | ((uint32_t)hdr[2] << 16) | ((uint32_t)hdr[3] << 24);
        if (magic == 0xa1b2c3d4)
            swap = 0;
        else if (magic == 0xd4c3b2a1)
            swap = 1;
        else {
            fprintf(stderr, "%s: unknown byte-order in cap file\n", filename);
            fprintf(stderr, "%s: unknown version %u.%u\n", filename, 41891, 41891);
            fprintf(stderr, "%s: unknown cap file linktype = %u (expected Ethernet or wifi)\n", filename, 41891);
            fprintf(stderr, "payloads: can't read from file '%s'\n", filename);
            fclose(fp);
            return -1;
        }
    }
#define RD16(b) (swap ? (((unsigned)(b)[0] << 8) | (b)[1]) : (((unsigned)(b)[1] << 8) | (b)[0]))
#define RD32(b) (swap ? (((uint32_t)(b)[0] << 24) | ((uint32_t)(b)[1] << 16) | ((uint32_t)(b)[2] << 8) | (b)[3]) \
                      : (((uint32_t)(b)[3] << 24) | ((uint32_t)(b)[2] << 16) | ((uint32_t)(b)[1] << 8) | (b)[0]))
    {
        unsigned vmaj = RD16(hdr + 4), vmin = RD16(hdr + 6);
        if (vmaj != 2 || vmin != 4)
            fprintf(stderr, "%s: unknown version %u.%u\n", filename, vmaj, vmin);
        linktype = RD32(hdr + 20);
    }
    for (;;) {
        unsigned char rh[16];
        unsigned char *pkt;
        uint32_t caplen;
        size_t off;
        n = fread(rh, 1, 16, fp);
        if (n < 16) {
            if (n == 0 && feof(fp)) {
                fprintf(stderr, "%s: %s\n", filename, strerror(ENOENT));
                fprintf(stderr, "payloads: can't read from file '%s'\n", filename);
            }
            break;
        }
        caplen = RD32(rh + 8);
        if (caplen > 1000000)
            break;
        pkt = malloc(caplen + 1);
        if (fread(pkt, 1, caplen, fp) != caplen) {
            free(pkt);
            break;
        }
        off = 0;
        if (linktype == 1) {
            unsigned et;
            if (caplen < 14) { free(pkt); continue; }
            et = ((unsigned)pkt[12] << 8) | pkt[13];
            off = 14;
            if (et == 0x8100 && caplen >= 18) {
                et = ((unsigned)pkt[16] << 8) | pkt[17];
                off = 18;
            }
            if (et != 0x0800) { free(pkt); continue; }
        }
        if (caplen >= off + 20 && (pkt[off] >> 4) == 4) {
            unsigned ihl = (pkt[off] & 0xF) * 4;
            unsigned proto = pkt[off + 9];
            if (proto == 17 && caplen >= off + ihl + 8) {
                unsigned dport = ((unsigned)pkt[off + ihl + 2] << 8) | pkt[off + ihl + 3];
                if (!udp_port_has_default_payload(dport)) {
                    fflush(stdout);
                    fprintf(stderr, "free(): invalid pointer\n");
                    signal(SIGABRT, SIG_DFL);
                    abort();
                }
            }
        }
        free(pkt);
    }
    fclose(fp);
    return 0;
}
