void load_service_probes(FILE *fp, const char *filename)
{
    char line[65536];
    unsigned ln = 0;
    struct SPProbe *probes = NULL;
    size_t nprobes = 0;
    struct RangeList excludes = {0};
    int have_exclude = 0;

    while (fgets(line, sizeof(line), fp)) {
        size_t i, n, tend;
        struct SPProbe *pr = nprobes ? &probes[nprobes - 1] : NULL;
        char tok[64];
        char msg[128];

        ln++;
        n = strlen(line);
        while (n && (line[n-1] == '\n' || line[n-1] == '\r'))
            line[--n] = '\0';
        if (line[0] == '\0' || line[0] == '#')
            continue;
        tend = 0;
        while (line[tend] && !isspace(line[tend] & 0xFF))
            tend++;
        i = skip_ws(line, tend);
        snprintf(tok, sizeof(tok), "%.*s", (int)tend, line);

        if (strcmp(tok, "Exclude") == 0) {
            if (nprobes) {
                sp_err(filename, ln, i, "'Exclude' directive only valid before any 'Probe'");
                continue;
            }
            rangelist_parse_ports(&excludes, line + i, NULL, 0);
            rangelist_sort(&excludes);
            have_exclude = 1;
            continue;
        }
        if (strcmp(tok, "Probe") == 0) {
            struct SPProbe np;
            if (sp_parse_probe(filename, ln, line, i, &np) != 0)
                continue;
            probes = realloc(probes, (nprobes + 1) * sizeof(*probes));
            probes[nprobes++] = np;
            continue;
        }
        if (strcmp(tok, "match") && strcmp(tok, "softmatch") && strcmp(tok, "ports")
            && strcmp(tok, "sslports") && strcmp(tok, "totalwaitms") && strcmp(tok, "tcpwrappedms")
            && strcmp(tok, "rarity") && strcmp(tok, "fallback")) {
            snprintf(msg, sizeof(msg), "unknown type: '%.*s'", (int)i, line);
            sp_err(filename, ln, i, msg);
            continue;
        }
        if (pr == NULL) {
            sp_err(filename, ln, i, "'directive only valid after a 'Probe'");
            continue;
        }
        if (strcmp(tok, "match") == 0 || strcmp(tok, "softmatch") == 0) {
            char *x = sp_parse_match(filename, ln, line, i);
            if (x) {
                pr->matches = realloc(pr->matches, (pr->match_count + 1) * sizeof(char *));
                pr->matches[pr->match_count++] = x;
            }
        } else if (strcmp(tok, "ports") == 0 || strcmp(tok, "sslports") == 0) {
            unsigned is_error = 0;
            struct RangeList *rl = (tok[0] == 'p') ? &pr->ports : &pr->sslports;
            struct RangeList tmp = {0};
            rangelist_parse_ports(&tmp, line + i, &is_error, 0);
            if (is_error || tmp.count == 0) {
                sp_err(filename, ln, i, "bad ports format");
                rangelist_free(&tmp);
                continue;
            }
            {
                size_t k;
                for (k = 0; k < tmp.count; k++)
                    rangelist_add_range(rl, tmp.list[k].begin, tmp.list[k].end);
                rangelist_sort(rl);
            }
            rangelist_free(&tmp);
        } else if (strcmp(tok, "rarity") == 0) {
            sp_number(filename, ln, line, i, &pr->rarity);
        } else if (strcmp(tok, "totalwaitms") == 0) {
            sp_number(filename, ln, line, i, &pr->totalwaitms);
        } else if (strcmp(tok, "tcpwrappedms") == 0) {
            sp_number(filename, ln, line, i, &pr->tcpwrappedms);
        }
    }
    sp_print_all(probes, nprobes, &excludes, have_exclude);
}
